export const allQuotes = [  { text: 'समय के पास इतना समय नहीं कि वो आपको दोबारा समय दे सके। इसलिए आज का सही उपयोग करें।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जो बदलता है वही आगे बढ़ता है। बदलाव से डरें नहीं, इसे एक अवसर के रूप में स्वीकार करें।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'सकारात्मकता एक विकल्प है जिसे आपको हर सुबह चुनना पड़ता है। खुश रहना सीखें।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'आपकी सोच ही आपकी सीमाएं तय करती है। बड़ा सोचें और खुद पर विश्वास रखें।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'सच्चा ज्ञान विनम्रता सिखाता है। घमंड सिर्फ अज्ञानता की निशानी है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जीवन में यदि शांति चाहते हैं तो दूसरों की कमियों को नहीं, खुद के सुधार को देखें।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'हर नया दिन आपकी जिंदगी में एक नया पन्ना जोड़ने का मौका है। इसे खूबसूरती से लिखें।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'ठोकर खाने से इंसान गिरता नहीं, बल्कि संभल कर चलना सीखता है। संघर्ष से घबराएं नहीं।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'वाणी में इतनी शक्ति है कि यह टूटे हुए रिश्तों को भी दोबारा जोड़ सकती है। मीठा बोलें।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'आप तब तक नहीं हारते जब तक आप कोशिश करना नहीं छोड़ देते। निरंतर प्रयास ही सफलता की कुंजी है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जिंदगी में कभी किसी को कम मत समझो, क्योंकि एक छोटा सा तिनका भी आँख में जाकर दर्द दे सकता है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'धैर्य रखना एक कड़वा पौधा है लेकिन इसका फल हमेशा मीठा होता है। संयम बनाए रखें।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जीवन की सबसे बड़ी खुशी उस काम को करने में है जिसे लोग कहते हैं कि आप नहीं कर सकते।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'सच्चा मित्र वही है जो आपके बुरे वक्त में भी आपकी ताकत बने, न कि आपकी कमजोरी।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'अगर आप किसी की मदद करने की स्थिति में हैं, तो बिना किसी स्वार्थ के अवश्य करें।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'गलतियाँ इंसान से ही होती हैं, लेकिन समझदार वो है जो उनसे सीखकर दोबारा न दोहराए।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'भाग्य के भरोसे रहने वाले अक्सर वही पाते हैं जो मेहनत करने वाले छोड़ देते हैं।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जीवन में सरलता ही सबसे बड़ा आभूषण है। दिखावे से दूर रहें और सादगी से जिएँ।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'संतुष्टि ही जीवन का सबसे बड़ा सुख और सबसे बड़ी संपत्ति है। संतोषी बनें।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'क्रोध में बोला गया एक कठोर शब्द इतना हानिकारक हो सकता है कि जीवनभर का प्रेम समाप्त कर दे।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'अपने सपनों को साकार करने के लिए लगन, मेहनत और अटूट विश्वास की आवश्यकता होती है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जो हर परिस्थिति में मुस्कुराना जानता है, वह दुनिया का सबसे अमीर व्यक्ति है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'समय से ज्यादा कीमती कुछ नहीं। इसे फालतू कामों में बर्बाद न करें, कुछ नया सीखें।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'विश्वास एक छोटा शब्द है लेकिन इसे कमाने में पूरी जिंदगी लग जाती है। इसे बनाए रखें।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'यदि आप सूर्य की तरह चमकना चाहते हैं, तो पहले सूर्य की तरह तपना सीखें।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'सच्ची प्रसन्नता केवल अपने कर्तव्यों का निष्ठापूर्वक पालन करने से ही प्राप्त हो सकती है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'अतीत को बदला नहीं जा सकता, पर वर्तमान को सुधारकर भविष्य को अवश्य संवारा जा सकता है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'इंसान अपने विचारों से बनता है, जैसा वह सोचता है वैसा ही उसका व्यक्तित्व हो जाता है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'कठिन रास्ते अक्सर सबसे सुंदर और अविस्मरणीय मंजिलों की ओर ले जाते हैं। धैर्य रखें।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'दूसरों को समझना ज्ञान है, लेकिन खुद को गहराई से जानना ही परम ज्ञान है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'सफलता केवल चाहने से नहीं मिलती, उसके लिए दिन-रात ईमानदारी से प्रयास करना पड़ता है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'यदि आपकी नियत साफ है, तो ईश्वर किसी न किसी रूप में आपकी मदद अवश्य करेंगे।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जीवन एक रंगमंच है और हम सभी इसके कलाकार हैं। अपना अभिनय बेहतरीन तरीके से करें।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जो लोग दूसरों की आँखों में खुशी लाते हैं, ईश्वर उनके जीवन को हमेशा खुशियों से भर देता है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'अपनी तुलना किसी और से न करें। हर फूल का अपना समय और अपनी खुशबू होती है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'मुस्कुराहट एक ऐसा उपहार है जो बिना कुछ खर्च किए भी दूसरों का दिन रोशन कर देता है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'मेहनत का फल और समस्या का हल थोड़ा देर से ही सही, लेकिन मिलता ज़रूर है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जीवन में वही व्यक्ति सफल होता है जो समय की कद्र करना जानता है। समय अनमोल है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'शांत मन से लिए गए फैसले हमेशा सही और जीवन को दिशा देने वाले होते हैं।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जब इरादे मजबूत हों, तो कोई भी रुकावट आपको आगे बढ़ने से नहीं रोक सकती।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'सच्चा सुख दूसरों को सुख देने में है। स्वार्थ से ऊपर उठकर जीना ही असली जीवन है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'आपकी आज की मेहनत आपके कल के सुनहरे भविष्य की नींव रखती है। जुटे रहें।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'अगर लोग आपके सीधेपन का फायदा उठाते हैं, तो भी अपनी अच्छाई को कभी मत छोड़िए।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'गलतियाँ सिखाती हैं कि प्रयास कैसे किया जाए। गिरने से न डरें, उठकर खड़े हों।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'विश्वास ही जीवन का आधार है। खुद पर और अपने कर्मों पर पूरा भरोसा रखें।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'वाणी का सदुपयोग करें। शब्द अगर मरहम का काम कर सकते हैं तो घाव भी दे सकते हैं।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'सकारात्मक दृष्टिकोण ही आपके जीवन को सुंदर और ऊर्जावान बनाता है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जो अपने काम से प्यार करता है, उसके लिए काम कभी बोझ नहीं बनता।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जीवन में ठहराव भी ज़रूरी है, ताकि आप आत्ममंथन कर सकें कि आप कहाँ जा रहे हैं।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'हर छोटा कदम एक दिन बड़े लक्ष्य तक पहुँचाता है। लगातार चलते रहें।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'Your limit is only your imagination. Push beyond the boundaries you set for yourself.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'Push yourself, because no one else is going to do it for you.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'Great things never come from comfort zones. Embrace the discomfort of growth.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'Dream it. Wish it. Do it. The steps between dreams and reality are action.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'Success doesn’t just find you. You have to go out and get it through persistent labor.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'The harder you work for something, the greater you’ll feel when you achieve it.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'Dream bigger. Do bigger. Live bigger. Let your life reflect your deepest potentials.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'Don’t stop when you are tired. Stop when you are done.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'Wake up with determination. Go to bed with satisfaction.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'Do something today that your future self will thank you for.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'Little things make big days. Consistency is the secret ingredient of great success.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'It’s going to be hard, but hard does not mean impossible.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'Don’t wait for opportunity. Create it with your own hands.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'Sometimes we’re tested not to show our weaknesses, but to discover our strengths.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'The key to success is to focus on goals, not obstacles.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'Believe you can and you’re halfway there. Faith moves mountains.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'Start where you are. Use what you have. Do what you can.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'Be lead by your dreams, not pushed by your problems.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'You are capable of more than you know. Never underestimate your power.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'Failure is not the opposite of success; it is part of success.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'The only way to achieve the impossible is to believe it is possible.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'Make each day your masterpiece. Life is a canvas of opportunities.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'If it matters to you, you will find a way. If not, you will find an excuse.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'Quiet progress is stronger than loud promises. Build in silence.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'Your daily habits design your long-term destination. Choose wisely.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'Success is a series of small wins repeated daily without fail.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'Keep moving. Even a slow step forward is a step closer to your dreams.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'Every morning brings a new choice. Choose action over delay.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'Be the energy you want to attract. Stay positive, work hard, make it happen.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'Nothing worth having comes easy. The struggle makes the victory sweet.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'Success is not just about what you accomplish, but what you inspire others to do.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'The path to success is always under construction. Embrace the journey.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'Action is the foundational key to all success. Without it, dreams die.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'Success is sweet, but its secret is sweat, determination, and discipline.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'Your focus determines your reality. Keep your eyes on the prize.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'The standard you walk past is the standard you accept. Aim for excellence.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'Excellence is not a skill, it is an attitude. Put your heart into everything.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'Success is doing ordinary things extraordinarily well, day after day.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'Winners focus on winning. Losers focus on winners. Keep your focus internal.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'Success is the quiet satisfaction of knowing you gave your absolute best.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'Opportunities are usually disguised as hard work, so most people don\'t recognize them.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'You don\'t have to be great to start, but you have to start to be great.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'Do not judge each day by the harvest you reap but by the seeds that you plant.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'The difference between a successful person and others is not lack of strength, but lack of will.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'To succeed in life, you need two things: ignorance of obstacles and confidence in success.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'If you want to achieve greatness stop asking for permission. Just execute.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'Build your own dreams, or someone else will hire you to build theirs.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'The best revenge is massive success. Let your results speak.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'Successful people do what unsuccessful people are not willing to do.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'Success is not final, failure is not fatal: it is the courage to continue that counts.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'Defeat is not bitter unless you swallow it. Learn, adapt, and rise.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'There are no secrets to success. It is the result of preparation, hard work, and learning from failure.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'Success is simple. Do what\'s right, the right way, at the right time.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'A successful man is one who can lay a firm foundation with the bricks others have thrown at him.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'The size of your success is measured by the strength of your desire.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'Always bear in mind that your own resolution to succeed is more important than any other.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'Don\'t count the days, make the days count. Success demands daily progress.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'Success is the child of audacity. Dare to take bold steps.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'The secret to success is to know something nobody else knows and execute it.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'Keep your face always toward the sunshine, and shadows will fall behind you.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'Technology is nothing. What\'s important is that you have a faith in people, that they\'re basically good and smart.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'Innovation is the ability to see change as an opportunity - not a threat.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'The great myth of our times is that technology is communication. Communication is human.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'Any sufficiently advanced technology is indistinguishable from magic. Keep creating magic.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'Humanity is acquiring all the right technology for all the wrong reasons. We must build responsibly.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'The technology of the future will be more human, intuitive, and seamless.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'We are building systems of unprecedented complexity. Let simplicity be your guide.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'Good engineering is not about complex solutions, but about simple answers to complex problems.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'Every great developer was once a beginner who refused to quit.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'Software is a great combination between artistry and engineering.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'The best way to predict the future is to invent it. Start coding it today.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'Computers are incredibly fast, accurate, and stupid. Humans are incredibly slow, inaccurate, and brilliant. Together they are powerful.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'Make it simple, make it memorable, make it invite interaction.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'Code is the language of the modern world. Write it like poetry.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'Technology should amplify human capability, not replace human connection.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'The web is more a social creation than a technical one. Keep people first.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'Design is not just what it looks like and feels like. Design is how it works.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'If you think technology will solve your problems, you don\'t understand technology.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'Technology is a useful servant but a dangerous master. Master the tools, don\'t let them master you.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'Focus on the user and all else will follow. Great design is invisible.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'Security is not a product, but a process. Build trust with every line of code.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'First, solve the problem. Then, write the code. Avoid premature complexity.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'Clean code always looks like it was written by someone who cares.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'The beautiful thing about code is that it is a canvas of pure logic and imagination.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'Optimism is a occupational hazard of programming. Test your assumptions.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'Programs must be written for people to read, and only incidentally for machines to execute.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'Continuous integration, continuous delivery, and continuous learning are the pillars of tech success.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'A user interface is like a joke. If you have to explain it, it’s not that good.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'Refactoring is not a chore; it is the process of keeping code healthy and clean.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'Technology should serve life, not the other way around. Keep your values clean.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'Critical thinking is the ability to think clearly and rationally, understanding the logical connection between ideas.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'Do not believe everything you think. Thoughts are just hypotheses, not absolute truths.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'The measure of intelligence is the ability to change. Question your oldest assumptions.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'To think is to say no to comfortable illusions. Search for reality, no matter how quiet.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'Wisdom is not about having answers, but about having the courage to ask difficult questions.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'The primary cause of unhappiness is never the situation but your thoughts about it.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'We don\'t see things as they are, we see them as we are. Examine your biases.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'He who knows only his own side of the case knows little of that. Listen to the opposite side.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'Read not to contradict and confute, nor to believe and take for granted, but to weigh and consider.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'A mind is like a parachute. It doesn\'t work if it isn\'t open.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'Do not let the noise of others\' opinions drown out your own inner logic.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'Truth is not found in crowds or consensus, but in evidence and objective logic.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'An opinion without evidence is just a rumor. Base your steps on facts.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'The greatest enemy of knowledge is not ignorance, it is the illusion of knowledge.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'Think for yourself and let others enjoy the privilege to do so too.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'The ability to ask the right question is more than half the battle of finding the answer.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'Intuition is a great starting point, but logic is the only reliable guide to the destination.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'Never attribute to malice that which is adequately explained by incompetence or error.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'A wise man adapts himself to circumstances, as water shapes itself to the vessel that contains it.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'Do not rush to judge. Rushing is a sign of emotion, not objective analysis.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'Intellectual clarity is a rare asset. Protect it by selecting clean inputs.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'It is easy to find reasons for what we want to believe. It is harder to find truth.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'Doubt is the beginning of wisdom. Do not fear it; let it drive you to research.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'Logic will get you from A to B. Imagination will take you everywhere, but logic keeps you safe.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'The mind that is too quick to agree is too lazy to think. Reflect before you accept.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'Learn to distinguish between what is urgent and what is truly important.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'The first step in critical thinking is to acknowledge your own limits and ignorance.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'No opinion is worth defending if it cannot withstand honest, logical examination.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'Clear thinking requires a quiet room and an honest heart. Find time to think daily.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'Question the source, verify the data, and test the conclusions before you act.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'सच्चा ज्ञान शब्दों में नहीं, आचरण में दिखता है। जो जानते हैं वो शांत रहते हैं, जो नहीं जानते वो शोर मचाते हैं।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'मुश्किलों से भागना बुझदिली है, उनका डटकर सामना करना ही असली मर्दानगी है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'खुद पर भरोसा रखना ही सफलता की पहली सीढ़ी है। जब पूरी दुनिया आप पर शक करे, तब भी अपने आप पर विश्वास रखें।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'कल की चिंता आज का सुकून छीन लेती है। जो आज में जीना सीख गया, उसने जीवन की कला सीख ली।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'सफलता का कोई छोटा रास्ता नहीं होता। हर बड़ी जीत के पीछे सालों की मेहनत और पसीना होता है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'वाणी में मिठास और दिल में सच्चाई हो तो इंसान हर जंग जीत सकता है। शब्दों में बहुत ताकत होती है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'बड़ा सोचो, मेहनत करो और तब तक मत रुको जब तक मंजिल हासिल न हो जाए। सपने बड़े होने चाहिए।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जब रास्ते बंद लगें, तो समझें कि नया रास्ता खोजने का समय आ गया है। बदलाव ही जीवन का नियम है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'क्रोध में लिया गया हर फैसला नुकसान पहुँचाता है। शांत रहकर विचार करना ही समझदारी है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'समय बहुत कीमती है, इसे दूसरों की बुराई करने में बर्बाद न करें। खुद को बेहतर बनाने में समय लगाएँ।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जो अपनी कमियों को स्वीकार करता है, वही एक दिन महान बनता है। सुधार हमेशा स्वीकार करने से शुरू होता है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जीवन एक अवसर है, इसे शिकायत करने में नहीं, कुछ नया करने में बिताएँ। कर्म ही असली पूजा है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'सच्चे मित्र वही हैं जो मुश्किल में साथ खड़े रहें। अच्छे दिनों में तो परछाई भी साथ चलती है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'धैर्य रखना सीखें, क्योंकि हर अच्छी चीज़ में समय लगता है। माली सौ घड़े सींचता है, तब फल आता है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'दूसरों की मदद करना ही सबसे बड़ा धर्म है। जो दूसरों को खुशी देता है, उसे खुद भी शांति मिलती है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जो बीत गया उसे भूल जाओ, जो आने वाला है उस पर ध्यान दो। आज का दिन तुम्हारा है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'मेहनत का फल और समस्या का हल थोड़ा देर से ही सही, मिलता ज़रूर है। हार मत मानो।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'अपनी सोच को हमेशा ऊँचा रखो, क्योंकि तुम्हारी सोच ही तुम्हारे भविष्य का निर्माण करती है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'संतुष्टि ही सबसे बड़ा धन है। जो कम में भी खुश है, वह दुनिया का सबसे अमीर इंसान है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'गलतियाँ इस बात का सबूत हैं कि आप प्रयास कर रहे हैं। कोशिश करने वालों की कभी हार नहीं होती।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'हर छोटा बदलाव एक बड़ी कामयाबी का हिस्सा होता है। रोज़ थोड़ा-थोड़ा सुधार लाएँ।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'अगर लक्ष्य पाना है तो तरीके बदलो, इरादे नहीं। मंजिल एक है, रास्ते अनेक हैं।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जो मुस्कुरा रहा है उसे दर्द ने पाला होगा, जो चल रहा है उसके पाँव में छाला होगा। संघर्ष ही जीवन है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'ईमानदारी एक महँगा शौक है, इसे हर कोई नहीं रख सकता। ईमानदार बनें और गर्व से जिएँ।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जब मन में विश्वास हो तो हर बाधा आसान हो जाती है। विश्वास ही तुम्हारी सबसे बड़ी शक्ति है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'खुद की तारीफ खुद ही करें, बुराई करने के लिए पूरी दुनिया तैयार बैठी है। खुश रहें।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जीवन में ऊँचा उठने के लिए किसी डिग्री की नहीं, अच्छे कर्मों की ज़रूरत होती है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'वक्त सबको मिलता है जिंदगी बदलने के लिए, पर जिंदगी दोबारा नहीं मिलती वक्त बदलने के लिए।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'शांत रहकर काम करें, आपकी सफलता को शोर मचाने दें। दिखावे से दूर रहें।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'सच्ची खुशी दूसरों को खुश देखने में है। अपने स्वार्थ से ऊपर उठकर जिएँ।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जिसका मन काबू में है, उसके लिए यह दुनिया बहुत खूबसूरत है। मन की शांति ही परम सुख है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'कठिन परिश्रम का कोई विकल्प नहीं है। भाग्य भी उन्हीं का साथ देता है जो मेहनत करते हैं।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जीतने का मज़ा तब आता है जब सभी आपके हारने का इंतज़ार कर रहे हों। हिम्मत न हारें।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जीवन में कभी निराश मत होना, क्योंकि कमजोर तुम्हारा वक्त है, तुम नहीं।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'सपनों को पाने के लिए समझदार नहीं, थोड़ा पागल बनना पड़ता है। लगन ही मंजिल तक पहुँचाती है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जो रातों को संघर्ष में बिताते हैं, वही सुबह सूरज की तरह चमकते हैं।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'इंसान का चरित्र उसके शब्दों से नहीं, उसके व्यवहार से तय होता है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'महानता कभी न गिरने में नहीं, बल्कि हर बार गिरकर उठ जाने में है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'यदि आप कुछ बड़ा करना चाहते हैं, तो पहले छोटे-छोटे लक्ष्यों को पूरा करना सीखें।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'सच्चा सम्मान कभी माँगा नहीं जाता, इसे अपने कर्मों से कमाया जाता है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'विश्वास एक ऐसी चीज़ है जो पत्थरों को भी भगवान बना सकती है, और शक इंसानों को भी शैतान।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'ज्ञान का सही उपयोग ही बुद्धिमानी है। सिर्फ जानना काफी नहीं, उसे अपनाना भी ज़रूरी है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'परिस्थितियाँ चाहे जैसी भी हों, मन को शांत रखना ही आपकी सबसे बड़ी जीत है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'अगर आप सूर्य की तरह चमकना चाहते हैं, तो पहले सूर्य की तरह जलना सीखें।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'दूसरों को समझना बुद्धिमानी है, खुद को समझना सच्चा ज्ञान है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जीवन में यदि शांति चाहते हैं, तो दूसरों से उम्मीदें रखना बंद करें और खुद पर निर्भर रहें।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जो मुस्कुरा रहा है, ज़रूरी नहीं कि वह खुश है। कभी-कभी मुस्कुराहट दर्द छुपाने का जरिया होती है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'मंजिल पाना तो तय है, बस आप अपने हौसलों को मजबूत बनाए रखें।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'आपका समय सीमित है, इसलिए इसे किसी और की जिंदगी जीकर व्यर्थ न करें।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जो लोग दूसरों की आँखों में आँसू लाते हैं, वे कभी खुद सच्चे मन से खुश नहीं रह सकते।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'सच्ची अमीरी पैसों से नहीं, दिल की उदारता और विचारों की अमीरी से होती है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जिंदगी में अगर कुछ बनना है तो दीपक की तरह बनें जो दूसरों के लिए जलता है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'मेहनत कभी बेकार नहीं जाती, चाहे उसका फल मिलने में थोड़ा वक्त लगे।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जो आसानी से मिल जाता है वह हमेशा नहीं रहता, और जो हमेशा रहता है वह आसानी से नहीं मिलता।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'सकारात्मक सोच ही जीवन में सफलता का आधार है। सकारात्मक रहें, आगे बढ़ें।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जब तक आप खुद पर विश्वास नहीं करते, तब तक भगवान भी आपकी मदद नहीं कर सकते।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'क्रोध एक ऐसा तेज़ाब है जो उस बर्तन को ज्यादा नुकसान पहुँचाता है जिसमें वह रखा जाता है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'इंसान अपनी परिस्थितियों से नहीं, अपनी प्राथमिकताओं से बड़ा बनता है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जो हर बात पर बहाने बनाते हैं, वे सफलता से हमेशा दूर ही रहते हैं।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जीवन में सबसे बड़ा सुख उस काम को करने में है जिसे लोग कहते हैं कि तुम नहीं कर सकते।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जब आप गिरते हैं, तो वह हार नहीं है। हार तब होती है जब आप उठने से मना कर देते हैं।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'अपनी तुलना किसी से न करें, आप जैसे भी हैं अपने आप में अद्वितीय हैं।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'वाणी का घाव तलवार के घाव से भी गहरा होता है। बोलने से पहले हमेशा सोचें।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'सच्चा सुख दूसरों की सेवा में है। निस्वार्थ कर्म ही परम आनंद है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जीवन में कुछ भी स्थायी नहीं है, इसलिए सुख और दुख दोनों का स्वागत समान रूप से करें।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जो अपने सपनों को सच करने का साहस रखते हैं, वे एक दिन इतिहास ज़रूर रचते हैं।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'धैर्य और परिश्रम के बल पर इंसान दुनिया की हर मुश्किल पर विजय पा सकता है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'अगर आप किसी की मदद नहीं कर सकते, तो कम से कम उन्हें नुकसान भी न पहुँचाएँ।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'सच्ची सफलता का पैमाना यह है कि आपने दूसरों के जीवन को कितना बेहतर बनाया।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'अपनी गलतियों को स्वीकार करना और उनसे सीखना ही परिपक्वता की पहचान है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'मनुष्य अपने विचारों से निर्मित एक प्राणी है, वह जैसा सोचता है वैसा ही बन जाता है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'बड़ा बनने के लिए दूसरों को छोटा दिखाना ज़रूरी नहीं है। खुद को बड़ा बनाएँ।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'हर सुबह एक नया अवसर लेकर आती है। उठें, मेहनत करें और आगे बढ़ें।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जो बीत गया उसे भूल जाएँ, क्योंकि आज में ही आने वाले कल की शुरुआत है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'सच्ची खुशी बाहरी चीज़ों में नहीं, हमारे भीतर की शांति में छिपी होती है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जब आपके इरादे मजबूत हों, तो हर मुश्किल रास्ता भी आसान हो जाता है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'भाग्य के भरोसे बैठने वाले हमेशा उतना ही पाते हैं जितना मेहनत करने वाले छोड़ देते हैं।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'यदि आप जीवन में कुछ नया पाना चाहते हैं, तो कुछ ऐसा करें जो आपने पहले कभी नहीं किया।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जिंदगी खेल की तरह है, अब यह आप पर निर्भर है कि आप खिलाड़ी बनना चाहते हैं या खिलौना।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जो मन को जीत लेता है, वह मानो पूरी दुनिया को जीत लेता है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'زندگی کو پُرسکون بنانا ہے تو دوسروں سے امیدیں رکھنا چھوڑ دو۔ سکون اپنے اندر تلاش کرو۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'محنت وہ چابی ہے جو کامیابی کے ہر بند دروازے کو کھول دیتی ہے۔ کوشش کرتے رہو۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'صبر کا پھل ہمیشہ میٹھا ہوتا ہے، چاہے اس میں تھوڑا وقت ہی کیوں نہ لگے۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'الفاظ انسان کی شخصیت کا آئینہ ہوتے ہیں۔ ہمیشہ سوچ سمجھ کر بولیں۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'سچی خوشی دوسروں کی مدد کرنے میں ہے۔ خود غرضی انسان کو اکیلا کر دیتی ہے۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'وقت سب سے بڑا استاد ہے، یہ انسان کو ہر وہ سبق سکھا دیتا ہے جو کوئی اور نہیں سکھا سکتا۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'خواب وہ نہیں جو سوتے ہوئے دیکھے جائیں، خواب وہ ہیں جو سونے نہ دیں۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'زندگی ایک خوبصورت سفر ہے، اس کا ہر لمحہ ہنسی خوشی گزاریں۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'غلطیاں اس بات کا ثبوت ہیں کہ آپ کوشش کر رہے ہیں۔ کوشش جاری رکھیں۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'خوبصورت سوچ ہر مشکل کو آسان بنا دیتی ہے۔ ہمیشہ مثبت سوچیں۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'سچے دوست وہی ہیں جو مشکل وقت میں ساتھ کھڑے رہیں۔ اچھے وقت میں تو سائے بھی ساتھ ہوتے ہیں۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'ہر صبح ایک نیا موقع لے کر آتی ہے۔ اٹھیں اور اپنی قسمت خود لکھیں۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'سچی امیری دل کی سخاوت اور اچھے اخلاق میں ہے۔ دولت تو آنی جانی ہے۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'جب ارادے پختہ ہوں تو منزلیں خود بخود آسان ہو جاتی ہیں۔ کبھی ہار مت مانو۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'صبر اور شکر زندگی کو آسان اور پُرسکون بنانے کے دو اہم ترین اصول ہیں۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'دوسروں کو معاف کرنا سیکھیں، اس سے آپ کا اپنا دل ہلکا اور پُرسکون ہو جائے گا۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'تعلیم وہ روشنی ہے جو جہالت کے اندھیروں کو دور کرتی ہے۔ علم حاصل کرتے رہو۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'انسان اپنے اعمال سے پہچانا جاتا ہے، باتوں سے تو ہر کوئی اچھا ہوتا ہے۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'کامیابی کا کوئی شارٹ کٹ نہیں ہوتا، یہ صرف اور صرف سخت محنت کا نتیجہ ہے۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'زندگی کو گزارو نہیں، بلکہ اسے خوبصورتی سے جینا سیکھو۔ یہ خدا کا تحفہ ہے۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'جس کا دل صاف ہے، اس کے لیے پوری کائنات خوبصورت ہے۔ دل کی صفائی سب سے اہم ہے۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'جو بیت گیا اسے بھول جاؤ، اور جو آنے والا ہے اس کو بہتر بنانے کی کوشش کرو۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'الفاظ میں وہ طاقت ہے جو کسی کا دل جیت بھی سکتی ہے اور کسی کا دل توڑ بھی سکتی ہے۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'زندگی میں کبھی بھی مایوس مت ہونا، کیونکہ مایوسی کفر ہے۔ ہمیشہ امید کا دامن تھامے رکھو۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'سچی کامیابی وہ ہے جس سے دوسروں کے چہروں پر مسکراہٹ آئے۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'کٹھن راستے اکثر خوبصورت منزلوں کی طرف لے جاتے ہیں۔ صبر سے کام لو۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'اپنے کردار کو ایسا بناؤ کہ لوگ آپ کی غیر موجودگی میں بھی آپ کی عزت کریں۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'خوش اخلاقی وہ سستی چیز ہے جس سے آپ پوری دنیا کو خرید سکتے ہیں۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'جب تک تم خود پر یقین نہیں رکھتے، کوئی تمہاری مدد نہیں کر سکتا۔ خود اعتمادی پیدا کرو۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'زندگی مختصر ہے، اسے اچھے کاموں اور محبتیں بانٹنے میں گزاریں۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'Love is a choice you make every single day, not just a feeling that comes and goes.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'True love means looking beyond flaws and cherishing the beautiful soul inside.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'Love does not dominate; it cultivates. It helps the other person grow into their best self.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'The greatest gift you can give someone is your time, attention, and unconditional love.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'Love is not about possession; it\'s about appreciation. Let the ones you love be free.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'To love is to place your happiness in the happiness of another.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'Love is the only language that can bridge any gap and heal any wound.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'Love doesn\'t make the world go round. Love is what makes the ride worthwhile.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'The most beautiful thing in the world is to see someone smile, and know that you are the reason.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'Love is when the other person\'s happiness is more important than your own.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'We are most alive when we are in love, connected deeply to another human being.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'There is only one happiness in this life, to love and be loved in return.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'Love is like the wind, you can\'t see it but you can feel it warming your heart.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'The best and most beautiful things in this world cannot be seen or even heard, but must be felt with the heart.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'To be brave is to love someone unconditionally, without expecting anything in return.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'Love is a friendship set to music. It brings harmony and peace to life.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'A loving heart is the beginning of all knowledge. It connects you to the universe.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'The giving of love is an education in itself. The more you give, the more you have.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'Love is the voice under all silences, the hope which has no opposite in fear.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'Where there is love there is peace, growth, and endless possibility.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'Love is a master key that opens the gates of happiness and mutual understanding.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'You don\'t love someone because they\'re perfect, you love them in spite of the fact that they\'re not.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'Love is the only force capable of transforming an enemy into a friend.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'A simple \'I love you\' means more than money. It is the language of the soul.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'Keep love in your heart. A life without it is like a sunless garden when the flowers are dead.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'Love is an act of endless forgiveness, a tender look which becomes a habit.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'The art of love is largely the art of persistence. Stay present, stay kind.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'We love because it\'s the only adventure that makes us truly human.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'Love is a soft promise that whatever comes, we will face it together.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'In the garden of humanity, love is the most beautiful and fragrant flower.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'Wisdom is the reward you get for a lifetime of listening when you would have preferred to talk.', author: 'Sohel Khan', category: 'WISDOM' },
  { text: 'A wise man learns by the mistakes of others, a fool by his own.', author: 'Sohel Khan', category: 'WISDOM' },
  { text: 'Knowing others is intelligence; knowing yourself is true wisdom.', author: 'Sohel Khan', category: 'WISDOM' },
  { text: 'The only true wisdom is in knowing you know nothing. Always remain a student.', author: 'Sohel Khan', category: 'WISDOM' },
  { text: 'Wisdom begins in wonder. Let your curiosity lead you to deeper understanding.', author: 'Sohel Khan', category: 'WISDOM' },
  { text: 'Honesty is the first chapter in the book of wisdom. Live a life of truth.', author: 'Sohel Khan', category: 'WISDOM' },
  { text: 'The journey of a thousand miles begins with one step. Walk with wisdom.', author: 'Sohel Khan', category: 'WISDOM' },
  { text: 'Wisdom is not a product of schooling but of the lifelong attempt to acquire it.', author: 'Sohel Khan', category: 'WISDOM' },
  { text: 'The art of being wise is the art of knowing what to overlook.', author: 'Sohel Khan', category: 'WISDOM' },
  { text: 'A fool speaks, the wise man listens. Silence is often the best reply.', author: 'Sohel Khan', category: 'WISDOM' },
  { text: 'Count your age by friends, not years. Count your life by smiles, not tears.', author: 'Sohel Khan', category: 'WISDOM' },
  { text: 'Wisdom is knowing what to do next; virtue is doing it.', author: 'Sohel Khan', category: 'WISDOM' },
  { text: 'Do not go where the path may lead, go instead where there is no path and leave a trail.', author: 'Sohel Khan', category: 'WISDOM' },
  { text: 'The only way to have a friend is to be one. Friendship is a mutual mirror.', author: 'Sohel Khan', category: 'WISDOM' },
  { text: 'Wisdom is the power to put our time and our knowledge to the proper use.', author: 'Sohel Khan', category: 'WISDOM' },
  { text: 'Patience is the companion of wisdom. Rushing leads to unnecessary errors.', author: 'Sohel Khan', category: 'WISDOM' },
  { text: 'A wise man will make more opportunities than he finds.', author: 'Sohel Khan', category: 'WISDOM' },
  { text: 'To live is the rarest thing in the world. Most people exist, that is all.', author: 'Sohel Khan', category: 'WISDOM' },
  { text: 'The seek for wisdom is the search for inner peace and ultimate truth.', author: 'Sohel Khan', category: 'WISDOM' },
  { text: 'He who has a why to live can bear almost any how.', author: 'Sohel Khan', category: 'WISDOM' },
  { text: 'Happiness is not something ready-made. It comes from your own deliberate actions.', author: 'Sohel Khan', category: 'WISDOM' },
  { text: 'The simple things are also the most extraordinary things, and only the wise can see them.', author: 'Sohel Khan', category: 'WISDOM' },
  { text: 'Never ruin an apology with an excuse. Own your actions and grow.', author: 'Sohel Khan', category: 'WISDOM' },
  { text: 'Wisdom is the quiet space between your thoughts and your reactions.', author: 'Sohel Khan', category: 'WISDOM' },
  { text: 'A wise person does not try to change others, but works on refining their own heart.', author: 'Sohel Khan', category: 'WISDOM' },
  { text: 'The truth is rarely pure and never simple. Look deeper to find it.', author: 'Sohel Khan', category: 'WISDOM' },
  { text: 'Do what you can, with what you have, where you are. That is practical wisdom.', author: 'Sohel Khan', category: 'WISDOM' },
  { text: 'Wisdom is the alignment of your thoughts, words, and actions with truth.', author: 'Sohel Khan', category: 'WISDOM' },
  { text: 'The greatest wisdom is to be kind. Kindness is a language the blind can see.', author: 'Sohel Khan', category: 'WISDOM' },
  { text: 'Let your wisdom be reflected in your calmness during a storm.', author: 'Sohel Khan', category: 'WISDOM' },
  { text: 'Life is short, and it is up to you to make it sweet, meaningful, and bright.', author: 'Sohel Khan', category: 'LIFE' },
  { text: 'The purpose of life is not to be happy. It is to be useful, honorable, and compassionate.', author: 'Sohel Khan', category: 'LIFE' },
  { text: 'Life is what happens when you\'re busy making other plans. Live in the present.', author: 'Sohel Khan', category: 'LIFE' },
  { text: 'In the end, it\'s not the years in your life that count. It\'s the life in your years.', author: 'Sohel Khan', category: 'LIFE' },
  { text: 'Life is 10% what happens to you and 90% how you react to it. You hold the controls.', author: 'Sohel Khan', category: 'LIFE' },
  { text: 'The biggest adventure you can take is to live the life of your dreams.', author: 'Sohel Khan', category: 'LIFE' },
  { text: 'Life is a mountain. Your goal is to find your path, not to reach the top first.', author: 'Sohel Khan', category: 'LIFE' },
  { text: 'Good friends, good books, and a sleepy conscience: this is the ideal life.', author: 'Sohel Khan', category: 'LIFE' },
  { text: 'Life is either a daring adventure or nothing at all. Choose adventure.', author: 'Sohel Khan', category: 'LIFE' },
  { text: 'You only live once, but if you do it right, once is enough.', author: 'Sohel Khan', category: 'LIFE' },
  { text: 'Life is really simple, but we insist on making it complicated. Keep it simple.', author: 'Sohel Khan', category: 'LIFE' },
  { text: 'The good life is one inspired by love and guided by knowledge.', author: 'Sohel Khan', category: 'LIFE' },
  { text: 'Life is a canvas. Splash all the paint on it you can. Make it colorful.', author: 'Sohel Khan', category: 'LIFE' },
  { text: 'To live is the rarest thing in the world. Most people just exist.', author: 'Sohel Khan', category: 'LIFE' },
  { text: 'Life is a story. Make yours a best seller through brave actions.', author: 'Sohel Khan', category: 'LIFE' },
  { text: 'Do not take life too seriously. You will never get out of it alive anyway.', author: 'Sohel Khan', category: 'LIFE' },
  { text: 'Life is a series of natural and spontaneous changes. Don\'t resist them; let reality flow.', author: 'Sohel Khan', category: 'LIFE' },
  { text: 'Keep your face always toward the sunshine, and shadows will fall behind you in life.', author: 'Sohel Khan', category: 'LIFE' },
  { text: 'The purpose of life is a life of purpose. Find what drives your heart.', author: 'Sohel Khan', category: 'LIFE' },
  { text: 'Life is like riding a bicycle. To keep your balance, you must keep moving.', author: 'Sohel Khan', category: 'LIFE' },
  { text: 'Every moment of life is a unique seed that can bloom into something beautiful.', author: 'Sohel Khan', category: 'LIFE' },
  { text: 'Life is a mirror. It smiles back at you when you smile at it.', author: 'Sohel Khan', category: 'LIFE' },
  { text: 'The best portion of a good man\'s life is his little, nameless, unremembered acts of kindness.', author: 'Sohel Khan', category: 'LIFE' },
  { text: 'Life is full of beauty. Notice it. Notice the bumble bee, the small child, and the smiling faces.', author: 'Sohel Khan', category: 'LIFE' },
  { text: 'Live in the sunshine, swim the sea, drink the wild air. Enjoy the gift of life.', author: 'Sohel Khan', category: 'LIFE' },
  { text: 'The quality of your life is determined by the quality of your thoughts.', author: 'Sohel Khan', category: 'LIFE' },
  { text: 'Life isn\'t about finding yourself. Life is about creating yourself.', author: 'Sohel Khan', category: 'LIFE' },
  { text: 'Enjoy the little things in life, for one day you may look back and realize they were the big things.', author: 'Sohel Khan', category: 'LIFE' },
  { text: 'Life is a journey, and every step teaches us something valuable.', author: 'Sohel Khan', category: 'LIFE' },
  { text: 'Make your life a reflection of your dreams, not your fears.', author: 'Sohel Khan', category: 'LIFE' },
  { text: 'I\'m not lazy, I\'m just on energy-saving mode. Please do not disturb.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'My bed is a magical place where I suddenly remember everything I forgot to do.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'I put the \'pro\' in procrastination. I\'ll finish this quote tomorrow.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'I\'m not arguing, I\'m just explaining why I\'m right in a loud voice.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'Common sense is like deodorant. The people who need it most never use it.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'I always wanted to be somebody, but now I realize I should have been more specific.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'I told my therapist about you. She laughed. We\'re both making progress.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'My fake plants died because I did not pretend to water them. Hard life.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'Behind every great man is a woman rolling her eyes. Classic team work.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'I am so clever that sometimes I don\'t understand a single word of what I am saying.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'People say nothing is impossible, but I do nothing every day. It\'s a skill.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'Age is an issue of mind over matter. If you don\'t mind, it doesn\'t matter.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'I\'m writing a book. I\'ve got the page numbers done. That\'s progress.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'My wallet is like an onion, opening it makes me cry.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'I\'m not clumsy. The floor just hates me, the table is a bully, and the door gets in my way.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'If you think nobody cares if you\'re alive, try missing a couple of payments.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'I want to be like a caterpillar. Eat a lot, sleep for a while, and wake up beautiful.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'I don\'t need a hairstylist, my pillow gives me a new hairstyle every morning.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'I\'m not short, I\'m just concentrated awesome.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'A day without sunshine is like, you know, night.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'We never really grow up, we only learn how to act in public.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'I don\'t suffer from insanity, I enjoy every minute of it.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'Light travels faster than sound. This is why some people appear bright until you hear them speak.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'I always learn from the mistake of others who took my advice.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'If at first you don\'t succeed, then skydiving definitely isn\'t for you.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'I\'m on a seafood diet. I see food and I eat it.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'I asked my dog for advice. He stared at me. Honestly, it was the best advice I got all week.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'Procrastination is the art of keeping up with yesterday.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'My goal for today is to be as productive as my cat. So, basically, sleeping all day.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'Never judge a book by its movie. The book usually has better snacks.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'A leader is best when people barely know he exists, when his work is done, they will say: we did it ourselves.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'Leadership is not about titles, positions, or flowcharts. It is about one life influencing another.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'The function of leadership is to produce more leaders, not more followers. Empower your team.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'A leader is one who knows the way, goes the way, and shows the way. Lead by example.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'Leadership is the capacity to translate vision into reality through collaborative action.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'Do not follow where the path may lead. Go instead where there is no path and leave a trail.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'The greatest leader is not necessarily the one who does the greatest things. He is the one that gets the people to do the greatest things.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'Before you are a leader, success is all about growing yourself. When you become a leader, success is all about growing others.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'To lead people, walk beside them. As for the best leaders, the people do not notice their existence.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'A good leader takes a little more than his share of the blame and a little less than his share of the credit.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'Outstanding leaders go out of their way to boost the self-esteem of their personnel.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'Leadership and learning are indispensable to each other. Keep expanding your mind.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'Average leaders raise the bar on themselves; good leaders raise the bar for others; great leaders inspire others to raise their own bar.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'The art of leadership is saying no, not saying yes. It is very easy to say yes.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'A true leader has the confidence to stand alone, the courage to make tough decisions, and the compassion to listen to the needs of others.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'A leader is a dealer in hope. Paint a bright future and work towards it.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'Management is doing things right; leadership is doing the right things.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'The challenge of leadership is to be strong, but not rude; be kind, but not weak; be bold, but not bully.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'The quality of a leader is reflected in the standards they set for themselves.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'A great leader\'s courage to fulfill his vision comes from passion, not position.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'Control is not leadership. Connection is leadership. Build bridges, not walls.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'A leader who does not listen to their team will eventually be surrounded by people who have nothing to say.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'Real leadership is defined by how you behave when the pressure is at its highest.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'Serve the team, protect their focus, and celebrate their victories. That is true leadership.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'The best leaders are teachers who make themselves obsolete over time.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'If your actions inspire others to dream more, learn more, do more and become more, you are a leader.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'Humility, integrity, and focus: the three pillars of sustainable leadership.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'A leader\'s job is to clear the path for their team, not to stand in the middle of it.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'Praise publicly, instruct privately. Respect is the currency of leadership.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'Great leaders do not create followers, they create new spaces for others to lead.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'Education is the passport to the future, for tomorrow belongs to those who prepare for it today.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'The roots of education are bitter, but the fruit is sweet. Keep learning.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'Education is not preparation for life; education is life itself.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'The beautiful thing about learning is that no one can take it away from you. It is yours forever.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'Live as if you were to die tomorrow. Learn as if you were to live forever.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'Intelligence plus character - that is the goal of true education.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'The mind is not a vessel to be filled, but a fire to be kindled.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'Learning never exhausts the mind. The more you know, the more you want to explore.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'Education is what remains after one has forgotten what one has learned in school.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'Tell me and I forget. Teach me and I remember. Involve me and I learn.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'The more that you read, the more things you will know. The more that you learn, the more places you\'ll go.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'Develop a passion for learning. If you do, you will never cease to grow.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'Education is the movement from darkness to light. Let the light in.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'He who opens a school door, closes a prison. Education is freedom.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'The capacity to learn is a gift; the ability to learn is a skill; the willingness to learn is a choice.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'An investment in knowledge pays the best interest. Compound your learning daily.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'Learning is a treasure that will follow its owner everywhere. Never stop seeking it.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'The whole purpose of education is to turn mirrors into windows.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'Change is the end result of all true learning. Let education transform you.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'You learn something new every day if you pay close attention.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'The expert in anything was once a beginner. Embrace the starting line.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'Do not limit a child to your own learning, for he was born in another time.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'Education is not the learning of facts, but the training of the mind to think.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'Self-education is, I firmly believe, the only kind of education there is.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'The goal of education is the advancement of knowledge and the dissemination of truth.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'A book is a device to ignite the imagination and expand the boundaries of the mind.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'Curiosity is the engine of education. Keep asking why and how.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'The best teachers show you where to look, but don\'t tell you what to see.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'Knowledge is power. Information is liberating. Education is the premise of progress.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'To learn is to live twice. Expand your horizon with every new lesson.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'The only journey is the one within. Explore the quiet spaces of your soul.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'Peace comes from within. Do not seek it without. Everything you need is already here.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'You are not a drop in the ocean. You are the entire ocean in a drop.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'The wound is the place where the Light enters you. Embrace the healing.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'Be the change that you wish to see in the world. Start with your own heart.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'The best way to find yourself is to lose yourself in the service of others.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'What we think, we become. What we feel, we attract. What we imagine, we create.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'The soul always knows what to do to heal itself. The challenge is to silence the mind.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'Your task is not to seek for love, but merely to seek and find all the barriers within yourself.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'Happiness is not something ready-made. It comes from your own peaceful actions.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'Yesterday I was clever, so I wanted to change the world. Today I am wise, so I am changing myself.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'The meaning of life is to find your gift. The purpose of life is to give it away.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'Quietness is a conversation with the universe. Learn the language of silence.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'Spirituality is not about rules; it is about connection, compassion, and inner peace.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'Let your life be a quiet reflection of your values, not your anxieties.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'The light you seek is already shining within you. Open the windows of your mind.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'Gratitude is the highest form of prayer. It aligns you with the abundance of life.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'When you lose touch with inner stillness, you lose touch with yourself.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'The present moment is filled with joy and happiness. If you are attentive, you will see it.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'Be still, and know that you are part of an infinite, loving universe.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'Love and compassion are necessities, not luxuries. Without them, humanity cannot survive.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'Your soul is a quiet garden. Water it with positive thoughts and silent meditation.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'The spiritual life does not remove us from the world but leads us deeper into it.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'Forgiveness is the key to unlocking the chains of anger and freeing your spirit.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'Awaken to the truth that you are a spiritual being having a temporary human experience.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'Trust the flow of the universe. What is meant for you will find you in perfect timing.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'Do not look for miracles. Be the miracle through your kindness and presence.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'Inner peace begins the moment you choose not to allow another person or event to control your emotions.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'The quieter you become, the more you are able to hear the wisdom of your heart.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'Let go of what was, accept what is, and have faith in what will be.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'Look deep into nature, and then you will understand everything better. Nature is the ultimate teacher.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'In every walk with nature one receives far more than he seeks. The quiet woods heal the soul.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'Nature does not hurry, yet everything is accomplished. Align your pace with her.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'The earth has music for those who listen. The rustle of leaves, the flow of rivers.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'Adopt the pace of nature: her secret is patience. Growth takes time.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'Heaven is under our feet as well as over our heads. Walk gently on the earth.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'The clearest way into the Universe is through a forest wilderness. Lose yourself to find yourself.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'Study nature, love nature, stay close to nature. It will never fail you.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'Nature is not a place to visit. It is home. We are part of this ecosystem.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'To sit in the shade on a fine day and look upon verdure is the most perfect refreshment.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'If you truly love nature, you will find beauty everywhere. In every leaf and stone.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'The mountains are calling and I must go. Find your wilderness and be free.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'In all things of nature there is something of the marvelous. Open your eyes to it.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'A morning walk in nature is a blessing for the whole day. Start fresh.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'Colors are the smiles of nature. Let the vibrant landscapes brighten your mind.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'Nature is the art of God. Appreciate the design of the universe.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'The forest is not silent; it speaks in a language of peace, growth, and eternity.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'Let the rain wash away your worries. Let the wind blow fresh ideas into your mind.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'Every flower is a soul blossoming in nature. Let yourself bloom in your own time.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'The earth laughs in flowers. Celebrate the joyful abundance of the earth.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'Sunsets are proof that endings can often be beautiful too. Rest and renew.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'Time spent among trees is never time wasted. It restores our mental health.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'Nature is a clean canvas of peace. Escape the noise and find your stillness there.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'Deep roots do not fear the storm. Build your foundation steady and strong.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'The ocean stirs the heart, inspires the imagination and brings eternal joy to the soul.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'We do not inherit the earth from our ancestors; we borrow it from our children. Protect it.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'Water is the driving force of all nature. Flow like water around every obstacle.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'Nature heals because it does not judge, it does not rush, it just exists.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'To walk in nature is to witness a thousand miracles in silence.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'The sky is an infinite reminder that our limitations are only temporary.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'Your mindset is the key to unlocking your potential. Train it to see opportunities in every challenge.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'A strong mindset does not mean you don\'t feel pain. It means you keep moving forward anyway.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'Repetition is the mother of all skills, including a positive and disciplined mindset.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'Reset your thoughts whenever you feel stuck. A bad hour does not define a bad day.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'Commitment is the true foundation of success. Let your actions match your resolutions.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'The mind is everything. What you think you become. Keep your thoughts clean and focused.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'Focus is the ultimate filter. Protect your best attention from the noise of the world.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'Start before you feel ready. Action builds the confidence you are waiting for.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'The quality of your mindset determines the quality of your decisions and your life.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'A positive mindset looks for solutions; a negative mindset looks for excuses.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'Discipline is the bridge between goals and accomplishment. Build it daily.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'Belief in yourself is a superpower. Once you have it, nothing can stop you.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'The only limits that exist are the ones you place on yourself. Expand your vision.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'Your attitude determines your altitude. Choose to look up and climb high.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'Change your thoughts and you change your world. Growth starts from within.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'A growth mindset believes that abilities can be developed through hard work and dedication.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'Failure is feedback. Use it to refine your strategy and try again with more wisdom.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'Do not let the opinion of others become your inner voice. Guard your thoughts.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'The greatest victory is the victory over your own doubts and fears.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'Stay patient. The best things in life take time, dedication, and persistent effort.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'A clear mindset is your competitive edge. Learn to silence the noise around you.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'You cannot control the storm, but you can control how you sail your ship. Stay steady.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'Your mindset is like a garden. If you don\'t plant flowers of positive thoughts, weeds of doubt will grow.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'Believe in the possibilities of today. Every morning is a fresh start for your mindset.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'The mind is a powerful servant but a terrible master. Keep it disciplined.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'Action is the antidote to fear and doubt. Move, decide, and learn.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'Let your progress be silent, and let your results demonstrate your growth.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'A resilient mindset views setbacks as setup for a stronger comeback.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'Focus on progress, not perfection. Every small step forward is a victory.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'Your thoughts are the blueprint of your future. Design it with courage and clarity.', author: 'Sohel Khan', category: 'MINDSET' },

  // ── MOTIVATION (12) ──
  { text: 'The only way to do great work is to love what you do. If you haven\'t found it yet, keep looking. Don\'t settle. As with all matters of the heart, you\'ll know when you find it.', author: 'Steve Jobs', category: 'MOTIVATION' },
  { text: 'Believe you can and you\'re halfway there. The moment you doubt whether you can fly, you cease forever to be able to do it. Self-belief is the foundation of all achievement.', author: 'Theodore Roosevelt', category: 'MOTIVATION' },
  { text: 'It does not matter how slowly you go as long as you do not stop. Progress is progress, no matter how small. Every step forward, no matter how tiny, brings you closer to your destination.', author: 'Confucius', category: 'MOTIVATION' },
  { text: 'Your time is limited, so don\'t waste it living someone else\'s life. Don\'t be trapped by dogma — which is living with the results of other people\'s thinking. Don\'t let the noise of others\' opinions drown out your own inner voice.', author: 'Steve Jobs', category: 'MOTIVATION' },
  { text: 'Everything you\'ve ever wanted is on the other side of fear. Fear is nothing more than a mental barrier. Break through it and you will discover a world of endless possibilities waiting for you to seize them.', author: 'George Addair', category: 'MOTIVATION' },
  { text: 'The future belongs to those who believe in the beauty of their dreams. Never stop dreaming because dreams are the seeds of reality. Water them with hard work and watch them bloom into something extraordinary.', author: 'Eleanor Roosevelt', category: 'MOTIVATION' },
  { text: 'Success is not final, failure is not fatal: it is the courage to continue that counts. The road to success is paved with setbacks, but those who keep moving forward despite the odds are the ones who ultimately triumph.', author: 'Winston Churchill', category: 'MOTIVATION' },
  { text: 'The only limit to our realization of tomorrow will be our doubts of today. Let us move forward with strong and active faith. The mind is everything; what you think, you become.', author: 'Franklin D. Roosevelt', category: 'MOTIVATION' },
  { text: 'Don\'t watch the clock; do what it does. Keep going. Time waits for no one, and the best way to make the most of it is to stay in motion, constantly pushing forward toward your goals.', author: 'Sam Levenson', category: 'MOTIVATION' },
  { text: 'Act as if what you do makes a difference. It does. Every action you take, no matter how small, creates a ripple effect that extends far beyond what you can see. You are more powerful than you realize.', author: 'William James', category: 'MOTIVATION' },
  { text: 'When you feel like quitting, remember why you started. Every successful person has a story of persistence. The difference between winners and quitters is that winners never gave up when things got hard.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'Hard times create strong people. Strong people create good times. Good times create weak people. And weak people create hard times. Stay strong through every season of life and break the cycle of mediocrity.', author: 'Sohel Khan', category: 'MOTIVATION' },
  // ── SUCCESS (12) ──
  { text: 'Success is not the key to happiness. Happiness is the key to success. If you love what you are doing, you will be successful. True success comes from within, not from external validation or material wealth.', author: 'Albert Schweitzer', category: 'SUCCESS' },
  { text: 'Don\'t be afraid to give up the good to go for the great. Many people settle for mediocrity because greatness requires sacrifice. The comfort zone is a beautiful place, but nothing ever grows there.', author: 'John D. Rockefeller', category: 'SUCCESS' },
  { text: 'The secret of success is to do the common things uncommonly well. Excellence is not about doing extraordinary things; it is about doing ordinary things with extraordinary dedication and attention to detail.', author: 'John D. Rockefeller Jr.', category: 'SUCCESS' },
  { text: 'Success usually comes to those who are too busy to be looking for it. Focus on the work, pour your heart into it, and success will follow naturally. The more you chase success, the more it will elude you.', author: 'Henry David Thoreau', category: 'SUCCESS' },
  { text: 'Opportunities don\'t happen. You create them. Stop waiting for the perfect moment. Take the moment and make it perfect. The world belongs to those who take initiative and create their own path.', author: 'Chris Grosser', category: 'SUCCESS' },
  { text: 'The only place where success comes before work is in the dictionary. There are no shortcuts to any place worth going. Hard work, discipline, and consistency are the only proven paths to lasting success.', author: 'Vidal Sassoon', category: 'SUCCESS' },
  { text: 'Success is walking from failure to failure with no loss of enthusiasm. Every setback is a setup for a comeback. The most successful people in history failed more times than most people ever try.', author: 'Winston Churchill', category: 'SUCCESS' },
  { text: 'I find that the harder I work, the more luck I seem to have. What people call luck is actually the intersection of preparation and opportunity. Put in the work and watch how lucky you become.', author: 'Thomas Jefferson', category: 'SUCCESS' },
  { text: 'Try not to become a man of success. Rather become a man of value. When you focus on adding value to the world and to others, success becomes a natural byproduct of your contribution.', author: 'Albert Einstein', category: 'SUCCESS' },
  { text: 'Success is not in what you have, but who you are. True wealth is measured not by the size of your bank account, but by the size of your heart and the depth of your character.', author: 'Bo Bennett', category: 'SUCCESS' },
  { text: 'Success is the sum of small efforts repeated day in and day out. Greatness is not achieved in a single leap but through consistent, deliberate practice over time. Show up every single day.', author: 'Robert Collier', category: 'SUCCESS' },
  { text: 'The difference between who you are and who you want to be is what you do. Dreams without action remain dreams. Action without dreams is wasted energy. Combine both and nothing can stop you.', author: 'Sohel Khan', category: 'SUCCESS' },
  // ── TECH (12) ──
  { text: 'The technology you use impresses no one. The experience you create with it is everything. The best technology is invisible — it seamlessly integrates into people\'s lives and makes things better without being noticed.', author: 'Sean Geraty', category: 'TECH' },
  { text: 'It\'s not that we use technology, we live technology. Technology has become so deeply intertwined with our daily existence that the boundary between human and machine continues to blur.', author: 'Godfrey Reggio', category: 'TECH' },
  { text: 'Any sufficiently advanced technology is indistinguishable from magic. What seems impossible today will be ordinary tomorrow. The pace of innovation keeps accelerating, turning science fiction into science fact.', author: 'Arthur C. Clarke', category: 'TECH' },
  { text: 'First we shape our tools, then our tools shape us. The relationship between humans and technology is reciprocal. We create technology, and in turn, technology reshapes how we think, communicate, and live.', author: 'Marshall McLuhan', category: 'TECH' },
  { text: 'Code is like humor. When you have to explain it, it\'s bad. Good code should be self-documenting, readable, and elegant. The best programmers write code that other humans can understand, not just machines.', author: 'Cory House', category: 'TECH' },
  { text: 'The computer was born to solve problems that did not exist before. Every technological breakthrough creates new challenges while solving old ones. Progress is a never-ending cycle of problem and solution.', author: 'Bill Gates', category: 'TECH' },
  { text: 'The advance of technology is based on making it fit in so that you don\'t really even notice it, so it\'s part of everyday life. The ultimate goal of any technology should be to enhance human capability effortlessly.', author: 'Bill Gates', category: 'TECH' },
  { text: 'Technology is best when it brings people together. The true measure of any technological advancement is not its complexity or speed, but its ability to connect humans and strengthen relationships.', author: 'Matt Mullenweg', category: 'TECH' },
  { text: 'Innovation distinguishes between a leader and a follower. Leaders don\'t wait for change to happen — they make it happen. They see possibilities where others see obstacles and dare to tread where others fear.', author: 'Steve Jobs', category: 'TECH' },
  { text: 'The science of today is the technology of tomorrow. Every line of research, every experiment, every discovery builds the foundation for the innovations that will define our future.', author: 'Edward Teller', category: 'TECH' },
  { text: 'Technology is a useful servant but a dangerous master. We must never let technology control us. Instead, we should harness it as a tool to amplify human creativity, compassion, and connection.', author: 'Christian Lous Lange', category: 'TECH' },
  { text: 'The greatest danger in times of turbulence is not the turbulence; it is to act with yesterday\'s logic. In a world of exponential change, adaptability is the single most important skill.', author: 'Peter Drucker', category: 'TECH' },
  // ── CRITICAL THINKING (12) ──
  { text: 'The unexamined life is not worth living. Self-reflection is the cornerstone of wisdom. Without questioning our own beliefs, actions, and motivations, we drift through life on autopilot.', author: 'Socrates', category: 'CRITICAL_THINKING' },
  { text: 'It is the mark of an educated mind to be able to entertain a thought without accepting it. True intelligence means being able to consider opposing viewpoints without immediate judgment.', author: 'Aristotle', category: 'CRITICAL_THINKING' },
  { text: 'We cannot solve our problems with the same thinking we used when we created them. To overcome challenges, we must elevate our consciousness and approach problems from entirely new perspectives.', author: 'Albert Einstein', category: 'CRITICAL_THINKING' },
  { text: 'Question everything. Learn something. Answer nothing. The wisest people are not those who have all the answers, but those who know how to ask the right questions.', author: 'Euripides', category: 'CRITICAL_THINKING' },
  { text: 'Thinking is the hardest work there is, which is probably the reason so few engage in it. Most people would rather accept comfortable lies than wrestle with uncomfortable truths.', author: 'Henry Ford', category: 'CRITICAL_THINKING' },
  { text: 'Wise men speak because they have something to say; fools because they have to say something. Before you speak, ask yourself: Is it true? Is it necessary? Is it kind? Is it adding value?', author: 'Plato', category: 'CRITICAL_THINKING' },
  { text: 'The important thing is not to stop questioning. Curiosity has its own reason for existing. Never lose a holy curiosity. Question everything you see, hear, and read.', author: 'Albert Einstein', category: 'CRITICAL_THINKING' },
  { text: 'To know what you know and what you do not know, that is true knowledge. Intellectual humility is recognizing the limits of your understanding and being open to learning from anyone, anywhere.', author: 'Confucius', category: 'CRITICAL_THINKING' },
  { text: 'An investment in knowledge pays the best interest. Every book you read, every skill you acquire, every lesson you learn compounds over time into a wealth that no market crash can take away.', author: 'Benjamin Franklin', category: 'CRITICAL_THINKING' },
  { text: 'Doubt is not a pleasant condition, but certainty is absurd. Absolute certainty is the enemy of growth. Embrace uncertainty and let it drive you to explore, discover, and understand more deeply.', author: 'Voltaire', category: 'CRITICAL_THINKING' },
  { text: 'The first principle is that you must not fool yourself — and you are the easiest person to fool. Be ruthless in examining your own biases and assumptions. Intellectual honesty starts from within.', author: 'Richard Feynman', category: 'CRITICAL_THINKING' },
  { text: 'Your assumptions are your windows on the world. Scrub them off every once in a while, or the light won\'t come in. Challenge your beliefs regularly to see the world as it truly is.', author: 'Isaac Asimov', category: 'CRITICAL_THINKING' },
  // ── HINDI (50) ──
  { text: 'अपने लक्ष्य को इतना बड़ा बनाओ कि रास्ते छोटे लगें। जब तुम्हारा सपना बड़ा होगा, तो हर चुनौती छोटी लगने लगेगी और तुम्हारा आत्मविश्वास अपने आप बढ़ता जाएगा।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जिंदगी में दो चीजें कभी मत छोड़ो — एक उम्मीद और दूसरा हौसला। ये दोनों ही तुम्हें हर मुश्किल से लड़ने की ताकत देते हैं और अंधेरे में भी रोशनी दिखाते हैं।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'कामयाबी उन्हीं को मिलती है जो अपनी गलतियों से सीखते हैं। गलतियां असफलता नहीं, सबक हैं। हर गलती तुम्हें एक कदम और मजबूत बनाती है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'मंजिल उन्हीं को मिलती है जिनके सपनों में जान होती है। पंखों से कुछ नहीं होता, हौसलों से उड़ान होती है। बस अपने सपने पर यकीन रखो और उड़ान भरो।', author: 'डॉ. ए.पी.जे. अब्दुल कलाम', category: 'HINDI' },
  { text: 'सपने वो नहीं जो हम सोते वक्त देखते हैं, सपने वो हैं जो हमें सोने नहीं देते। अगर तुम्हारा लक्ष्य तुम्हें रातों की नींद नहीं लेने देता, तो समझ लो तुम सही रास्ते पर हो।', author: 'डॉ. ए.पी.जे. अब्दुल कलाम', category: 'HINDI' },
  { text: 'जिंदगी एक खेल है, इसे खेलना सीखो। हार और जीत दोनों को समान भाव से स्वीकार करो। जो खिलाड़ी हार से नहीं डरता, वही असली विजेता होता है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'सफलता का कोई शॉर्टकट नहीं होता, मेहनत ही एकमात्र रास्ता है। जो लोग शॉर्टकट ढूंढते हैं, वे अक्सर लंबा रास्ता तय करते हैं। सीधा रास्ता ही सबसे छोटा रास्ता है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'उठो, जागो और तब तक मत रुको जब तक लक्ष्य प्राप्त न हो जाए। जीवन एक अवसर है, इसे व्यर्थ मत जाने दो। हर सुबह एक नया मौका लेकर आती है।', author: 'स्वामी विवेकानंद', category: 'HINDI' },
  { text: 'कठिनाइयों से भागो मत, उनका सामना करो। जो तूफानों से लड़ता है, वही समंदर पार करता है। हर मुश्किल तुम्हें कल के लिए और मजबूत बनाती है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जो खुद पर विश्वास करते हैं, वही दुनिया जीतते हैं। आत्मविश्वास वो हथियार है जिससे तुम कोई भी जंग जीत सकते हो। खुद पर भरोसा रखो, दुनिया तुम पर भरोसा करेगी।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जीवन में जो कुछ भी बड़ा हासिल होता है, वो पहले सपने में आता है। हर बड़ी उपलब्धि की शुरुआत एक छोटे से विचार से होती है। अपने विचारों को कभी कम मत आंको।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'अकेले चलो, अगर कोई साथ नहीं देता। रास्ता खुद बन जाएगा। दुनिया उन्हीं का साथ देती है जो खुद पर भरोसा करते हैं। अकेले चलना सीखो, फिर देखो कितने लोग तुम्हारे पीछे चलते हैं।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'मेहनत इतनी खामोशी से करो कि सफलता शोर मचा दे। जब तुम अपने काम में डूब जाते हो, तो दुनिया खुद तुम्हारी तारीफ करने लगती है। कर्म बोलता है, शब्द नहीं।', author: 'डॉ. ए.पी.जे. अब्दुल कलाम', category: 'HINDI' },
  { text: 'जो हम सोचते हैं वो हम बन जाते हैं। तुम्हारी सोच ही तुम्हारी पहचान है। अगर तुम बड़ा सोचोगे, तो एक दिन बड़े बन जाओगे। कोई भी तुम्हें रोक नहीं सकता।', author: 'महात्मा गांधी', category: 'HINDI' },
  { text: 'मन के हारे हार है, मन के जीते जीत। जीवन की सबसे बड़ी जंग खुद से होती है। जो खुद को जीत लेता है, उसे दुनिया कोई नहीं हरा सकता।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'हिम्मत वह नहीं जो गिरने से बचाए, हिम्मत वो है जो गिरने के बाद उठना सिखाए। हर कोई गिरता है, लेकिन सिर्फ बहादुर लोग ही बार-बार उठते हैं।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जो वक्त का इंतजार करते हैं, वक्त उनका नहीं होता। सही समय का इंतजार मत करो — जो समय तुम्हारे पास है, उसे ही सही बना लो। कल कभी नहीं आता।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'बुरा जो देखन मैं चला, बुरा न मिलिया कोय। जो मन खोजा आपना, तो मुझसे बुरा न कोय। दुनिया में बुराई ढूंढने से पहले खुद के अंदर झांको।', author: 'संत कबीर दास', category: 'HINDI' },
  { text: 'दुख में सुमिरन सब करें, सुख में करे न कोय। जो सुख में सुमिरन करे, तो दुख काहे को होय। ईश्वर को सिर्फ मुश्किल वक्त में नहीं, हर वक्त याद करो।', author: 'संत कबीर दास', category: 'HINDI' },
  { text: 'जीवन एक उपहार है, इसे स्वीकार करो और हर पल को जियो। कल की चिंता और कल के पछतावे में अपना आज मत खराब करो। आज में जीना सीखो।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'कोशिश करने वालों की कभी हार नहीं होती। चाहे कितनी भी बड़ी बाधा आए, हार नहीं माननी चाहिए। लहरों से डरकर नौका पार नहीं होती।', author: 'हरिवंश राय बच्चन', category: 'HINDI' },
  { text: 'हर सुबह एक नई उम्मीद लेकर आती है और हर रात एक नया सबक सिखाकर जाती है। जीवन का हर दिन एक नई सीख है, बस आंखें खोलकर देखने की जरूरत है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'सपने बड़े देखो, मेहनत उतनी ही करो। छोटे सपने तुम्हें कभी बड़ा इंसान नहीं बना सकते। आसमान की ऊंचाइयों को छूने के लिए उतनी ही ऊंची सोच रखनी होगी।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'कर्म करो, फल की चिंता मत करो। तुम्हारा काम है प्रयास करना, परिणाम की जिम्मेदारी ईश्वर पर छोड़ दो। बस अपना शत-प्रतिशत दो और बाकी समय पर छोड़ दो।', author: 'भगवद् गीता', category: 'HINDI' },
  { text: 'एक छोटी सी सकारात्मक सोच आपकी पूरी जिंदगी बदल सकती है। नकारात्मकता एक जहर है जो धीरे-धीरे तुम्हें अंदर से खोखला कर देती है। सकारात्मक सोचो, सकारात्मक रहो।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जो बीत गया सो बीत गया, अब आगे बढ़ो। अतीत की गलतियों में उलझकर मत रहो। उनसे सीखो और आगे का रास्ता तय करो। बीते हुए कल को बदला नहीं जा सकता।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'बिना संघर्ष के कुछ भी हासिल नहीं होता। सोना भी आग में तपकर ही कुंदन बनता है। संघर्ष ही जीवन का असली सौंदर्य है, इससे भागो मत, इसे गले लगाओ।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'हार मत मानो, क्योंकि असंभव सिर्फ एक राय है, सच्चाई नहीं। जिसे दुनिया नामुमकिन कहती है, वह किसी के लिए मुमकिन होता है। बस वह कोई तुम बनो।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'समय बर्बाद मत करो, क्योंकि यही जिंदगी है। जो पल एक बार चला जाता है, वो कभी वापस नहीं आता। हर सेकंड कीमती है। इसका सही उपयोग करो।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'पहले खुद को बदलो, फिर दुनिया बदलेगी। दुनिया को बदलने की चाहत रखने से पहले खुद को बदलो। जब तुम बदलोगे, तो तुम्हारी दुनिया अपने आप बदल जाएगी।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'दूसरों की तारीफ करना सीखो, यह सबसे बड़ी नेकी है। किसी की तारीफ करने से तुम्हारा कुछ नहीं जाता, बल्कि रिश्ते मजबूत होते हैं और दिल जीते जाते हैं।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जीवन में लक्ष्य होना जरूरी है, वरना जीवन दिशाहीन हो जाता है। बिना मंजिल के सफर का कोई मतलब नहीं। एक स्पष्ट लक्ष्य तय करो और उस पर डटे रहो।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'खुद को पहचानो, यही सबसे बड़ी सफलता है। जब तक तुम खुद को नहीं जानते, तब तक तुम दुनिया को क्या जानोगे। खुद की पहचान ही असली ज्ञान है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जो दूसरों के लिए जीता है, वही सच्चा इंसान है। सिर्फ अपने लिए जीना तो जानवर भी जानते हैं। इंसान वही है जो दूसरों की भलाई में अपनी खुशी ढूंढे।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'मंजिल पाने का जुनून हो तो रास्ते खुद बन जाते हैं। जब इरादे मजबूत हों, तो राहें अपने आप निकल आती हैं। बस चलने का जुनून चाहिए, रास्ता मिल ही जाएगा।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'ज्ञान ही शक्ति है। यह दुनिया का सबसे बड़ा हथियार है जिसे कोई चुरा नहीं सकता। जितना ज्यादा ज्ञान बांटोगे, उतना ही बढ़ेगा।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'सब्र का फल मीठा होता है। जल्दबाजी में किए गए काम अक्सर पछतावे का कारण बनते हैं। धैर्य रखो, सही समय का इंतजार करो, सफलता जरूर मिलेगी।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'इंसानियत ही सबसे बड़ा धर्म है। जाति, धर्म, रंग, भाषा से ऊपर उठकर सबसे पहले इंसान बनो। इंसानियत से बड़ा कोई मजहब नहीं।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'परिश्रम का कोई तोड़ नहीं है। भाग्य भी उन्हीं का साथ देता है जो मेहनत करते हैं। भाग्य के भरोसे बैठे रहने वाले कभी सफल नहीं होते।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'स्वास्थ्य ही सबसे बड़ा धन है। तन सेहतमंद होगा तो मन भी स्वस्थ रहेगा। धन-दौलत सब बाद में, पहले अपनी सेहत का ख्याल रखो।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जहां प्रेम है, वहां ईश्वर है। प्रेम ही ईश्वर का सबसे बड़ा रूप है। जहां सच्चा प्रेम होता है, वहां किसी मंदिर या मस्जिद की जरूरत नहीं होती।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'अनुभव सबसे बड़ा गुरु है। किताबों से ज्यादा जिंदगी सिखाती है। हर ठोकर एक सबक है, हर हार एक अनुभव। इनसे सीखो और आगे बढ़ो।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'दूसरों की मदद करने से बड़ा कोई पुण्य नहीं। जब तुम किसी जरूरतमंद की मदद करते हो, तो ईश्वर खुद तुम्हारी मदद करता है। सेवा ही सबसे बड़ा धर्म है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जिंदगी खूबसूरत है, बस नजरिया बदलने की देर है। सब कुछ तुम्हारे पास है, बस देखने का तरीका बदलो। कमियों की जगह खूबियां गिनो, जिंदगी खुद-ब-खुद खूबसूरत लगने लगेगी।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'पहला कदम सबसे मुश्किल होता है, लेकिन एक बार चल पड़े तो मंजिल खुद-ब-खुद करीब आने लगती है। शुरुआत करो, बाकी सब अपने आप होता जाएगा।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जीतने वाले अलग चीजें नहीं करते, वे चीजों को अलग तरीके से करते हैं। सफलता का राज किसी खास योग्यता में नहीं, बल्कि सोचने के अनोखे तरीके में छिपा है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'हर बड़ी सफलता के पीछे अनगिनत छोटी-छोटी असफलताएं छिपी होती हैं। जो चेहरे की मुस्कान देखते हैं, वो आंखों के आंसू नहीं देखते।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'ईमानदारी सबसे महंगी चीज है, लेकिन हर कोई इसकी कीमत नहीं चुका सकता। ईमानदार रहना मुश्किल जरूर है, लेकिन असंभव नहीं।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'अच्छे दोस्त वो नहीं जो हर वक्त साथ रहते हैं, बल्कि वो हैं जो मुश्किल वक्त में भी साथ खड़े रहते हैं। सच्ची दोस्ती परख मुश्किलों में होती है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जब तक तुम प्रयास नहीं करते, तब तक तुम्हें पता भी नहीं चलेगा कि तुम क्या कर सकते हो। अपनी सीमाओं को तोड़ो और अपनी असली ताकत पहचानो।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'दुनिया उनकी इज्जत करती है जो खुद की इज्जत करते हैं। आत्मसम्मान से बड़ी कोई पूंजी नहीं। इसे कभी मत खोना।', author: 'Sohel Khan', category: 'HINDI' },
  // ── URDU (30) ──
  { text: 'خدا اس کی مدد کرتا ہے جو خود اپنی مدد کرتا ہے۔ جب تم خود کوشش کرتے ہو، تو خدا بھی تمہارے لیے راستے آسان کر دیتا ہے۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'محنت کا کوئی متبادل نہیں ہے۔ چاہے دنیا کی ساری دولت بھی کیوں نہ مل جائے، محنت کے بغیر کامیابی کا کوئی شارٹ کٹ نہیں ہوتا۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'جہاں چاہ وہاں راہ۔ جب ارادہ پختہ ہو، تو راستے خود بخود بن جاتے ہیں۔ بس چلنے کا حوصلہ چاہیے۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'اپنے خوابوں کو اتنا بڑا بناؤ کہ راستے چھوٹے لگیں۔ بڑے خواب دیکھو، پھر انہیں حقیقت بنانے کے لیے دن رات محنت کرو۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'زندگی میں دو چیزیں کبھی مت چھوڑو — ایک امید اور دوسرا حوصلہ۔ یہ دونوں ہی تمہیں ہر مشکل سے لڑنے کی طاقت دیتے ہیں۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'کامیابی انہیں کو ملتی ہے جو اپنی غلطیوں سے سیکھتے ہیں۔ غلطیاں ناکامی نہیں، سبق ہیں۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'خواب وہ نہیں جو ہم سوتے وقت دیکھتے ہیں، خواب وہ ہیں جو ہمیں سونے نہیں دیتے۔', author: 'ڈاکٹر اے پی جے عبدالکلام', category: 'URDU' },
  { text: 'زندگی ایک کھیل ہے، اسے کھیلنا سیکھو۔ ہار یا جیت قسمت کی بات ہے، لیکن کوشش کرنا تمہارے ہاتھ میں ہے۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'اٹھو، جاگو اور تب تک مت رکو جب تک منزل حاصل نہ ہو جائے۔ زندگی ایک موقع ہے، اسے ضائع مت کرو۔', author: 'سوامی ویویکانند', category: 'URDU' },
  { text: 'مشکلات سے بھاگو مت، ان کا سامنا کرو۔ جو طوفانوں سے لڑتا ہے، وہی سمندر پار کرتا ہے۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'جو خود پر یقین رکھتے ہیں، وہی دنیا جیتتے ہیں۔ خود اعتمادی وہ ہتھیار ہے جس سے تم کوئی بھی جنگ جیت سکتے ہو۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'خود پر یقین رکھنے والے لوگ ہی تاریخ بناتے ہیں۔ جو اپنی صلاحیتوں پر شک کرتے ہیں، وہ کبھی بڑے نہیں بن سکتے۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'خوش رہنا سب سے بڑی کامیابی ہے۔ دولت اور شہرت سے زیادہ اہم دل کا سکون ہے۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'وقت کسی کے لیے نہیں رکتا، اس لیے ابھی شروع کرو۔ کل کا انتظار کرنے والے کبھی کچھ نہیں کر پاتے۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'عشق نے غالبؔ نکما کر دیا، ورنہ ہم بھی آدمی تھے کام کے۔ محبت انسان کو بدل دیتی ہے۔', author: 'مرزا غالب', category: 'URDU' },
  { text: 'ہزاروں خواہشیں ایسی کہ ہر خواہش پہ دم نکلے۔ بہت نکلے مرے ارمان لیکن پھر بھی کم نکلے۔', author: 'مرزا غالب', category: 'URDU' },
  { text: 'خودی کو کر بلند اتنا کہ ہر تقدیر سے پہلے، خدا بندے سے خود پوچھے بتا تیری رضا کیا ہے۔', author: 'علامہ اقبال', category: 'URDU' },
  { text: 'تعلیم سب سے طاقتور ہتھیار ہے جس سے آپ دنیا بدل سکتے ہیں۔ علم سے بڑھ کر کوئی طاقت نہیں۔', author: 'نیلسن منڈیلا', category: 'URDU' },
  { text: 'محنت اتنی خاموشی سے کرو کہ کامیابی شور مچا دے۔', author: 'ڈاکٹر اے پی جے عبدالکلام', category: 'URDU' },
  { text: 'ہر صبح ایک نئی امید لے کر آتی ہے۔ ہر دن ایک نیا موقع ہے کچھ بہتر کرنے کا۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'جو شخص خود کو ہرا دیتا ہے، وہ دنیا کو ہرا سکتا ہے۔ سب سے بڑی جیت خود پر جیت ہے۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'صبر کا پھل میٹھا ہوتا ہے۔ جلد بازی میں کیے گئے کام اکثر پچھتاوے کا سبب بنتے ہیں۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'علم ہی طاقت ہے۔ یہ دنیا کا سب سے بڑا ہتھیار ہے جسے کوئی چرا نہیں سکتا۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'دنیا میں کچھ بھی ناممکن نہیں ہے۔ لفظ ناممکن صرف ایک رائے ہے، حقیقت نہیں۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'اچھے اعمال کبھی رائیگاں نہیں جاتے۔ جو بھلائی تم کرتے ہو، وہ کسی نہ کسی صورت میں تمہارے پاس واپس آتی ہے۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'زندگی چھوٹی ہے، اسے بڑے کاموں کے لیے استعمال کرو۔ چھوٹی سوچ چھوٹی زندگی دیتی ہے۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'ہار تب نہیں ہوتی جب آپ گرتے ہیں، ہار تب ہوتی ہے جب آپ اٹھتے نہیں۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'محبت انسان کو بدل دیتی ہے۔ جس سے محبت ہو جائے، وہی سب سے خوبصورت لگنے لگتا ہے۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'دوست وہ نہیں جو ہر وقت ساتھ ہوں، دوست وہ ہیں جو مشکل وقت میں بھی ساتھ کھڑے رہیں۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'سچ بولنے والے کو کبھی ڈرنے کی ضرورت نہیں ہوتی۔ سچ سب سے بڑی طاقت ہے۔', author: 'Sohel Khan', category: 'URDU' },
  // ── LOVE (12) ──
  { text: 'Love is not about how many days, months, or years you have been together. Love is about how much you love each other every single day, even when things get difficult and the world seems against you.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'The best thing to hold onto in life is each other. When everything else fades away — money, fame, possessions — love remains the only thing that truly matters.', author: 'Audrey Hepburn', category: 'LOVE' },
  { text: 'Where there is love there is life. Love is the spark that ignites the human spirit. Without love, existence is merely survival, not living.', author: 'Mahatma Gandhi', category: 'LOVE' },
  { text: 'Love recognizes no barriers. It jumps hurdles, leaps fences, penetrates walls to arrive at its destination full of hope. True love is unstoppable.', author: 'Maya Angelou', category: 'LOVE' },
  { text: 'To love and be loved is to feel the sun from both sides. There is no greater warmth in this world than the warmth of mutual, unconditional love.', author: 'David Viscott', category: 'LOVE' },
  { text: 'Love is composed of a single soul inhabiting two bodies. When two people are truly in love, they become two halves of one complete whole.', author: 'Aristotle', category: 'LOVE' },
  { text: 'The greatest happiness of life is the conviction that we are loved — loved for ourselves, or rather, loved in spite of ourselves.', author: 'Victor Hugo', category: 'LOVE' },
  { text: 'Love all, trust a few, do wrong to none. Be generous with your heart, but wise with your trust. That is the secret to a life filled with meaningful relationships.', author: 'William Shakespeare', category: 'LOVE' },
  { text: 'A loving heart is the truest wisdom. Intelligence without compassion is dangerous. Knowledge without kindness is hollow. Love is the highest form of intelligence.', author: 'Charles Dickens', category: 'LOVE' },
  { text: 'In the end, the love you take is equal to the love you make. You receive from the universe exactly what you put into it. Give love and love will find you.', author: 'Paul McCartney', category: 'LOVE' },
  { text: 'Love is the only force capable of transforming an enemy into a friend. Hatred multiplies hatred, but love has the power to break the cycle and create peace where there was conflict.', author: 'Martin Luther King Jr.', category: 'LOVE' },
  { text: 'The best love is the kind that awakens the soul and makes us reach for more, that plants a fire in our hearts and brings peace to our minds.', author: 'Nicholas Sparks', category: 'LOVE' },
  // ── WISDOM (12) ──
  { text: 'The only true wisdom is in knowing you know nothing. The moment you think you know everything, you stop learning. Humility is the beginning of all wisdom.', author: 'Socrates', category: 'WISDOM' },
  { text: 'Knowledge speaks, but wisdom listens. Anyone can talk, but only the truly wise understand the value of silence and the power of truly hearing what others have to say.', author: 'Jimi Hendrix', category: 'WISDOM' },
  { text: 'Turn your wounds into wisdom. Every painful experience carries within it the seed of growth. The difference between suffering and wisdom is whether you learn from your pain.', author: 'Oprah Winfrey', category: 'WISDOM' },
  { text: 'The fool doth think he is wise, but the wise man knows himself to be a fool. Self-awareness is the first step toward genuine wisdom.', author: 'William Shakespeare', category: 'WISDOM' },
  { text: 'Wisdom begins in wonder. Curiosity is the engine of growth. The wisest people never lose their childlike sense of amazement at the world around them.', author: 'Socrates', category: 'WISDOM' },
  { text: 'By three methods we may learn wisdom: First, by reflection, which is noblest; Second, by imitation, which is easiest; and third by experience, which is the bitterest.', author: 'Confucius', category: 'WISDOM' },
  { text: 'Honesty is the first chapter in the book of wisdom. Without truthfulness — first to yourself and then to others — all other knowledge is built on a shaky foundation.', author: 'Thomas Jefferson', category: 'WISDOM' },
  { text: 'It is better to remain silent at the risk of being thought a fool, than to talk and remove all doubt of it. Sometimes the wisest thing you can say is nothing at all.', author: 'Maurice Switzer', category: 'WISDOM' },
  { text: 'Silence is the sleep that nourishes wisdom. In the noise of the modern world, the ability to find quiet moments for reflection is a superpower.', author: 'Francis Bacon', category: 'WISDOM' },
  { text: 'Not everything that is faced can be changed, but nothing can be changed until it is faced. Wisdom is knowing what you can control and having the courage to act on it.', author: 'James Baldwin', category: 'WISDOM' },
  { text: 'The simple things are also the most extraordinary things, and only the wise can see them. Happiness is found not in grand gestures, but in everyday moments.', author: 'Paulo Coelho', category: 'WISDOM' },
  { text: 'Wisdom is not a product of schooling but of the lifelong attempt to acquire it. Formal education gives you knowledge, but life experience gives you wisdom.', author: 'Albert Einstein', category: 'WISDOM' },
  // ── LIFE (12) ──
  { text: 'Life is what happens when you\'re busy making other plans. While you are worrying about tomorrow, today is slipping away. Be present. Be here now.', author: 'John Lennon', category: 'LIFE' },
  { text: 'The purpose of our lives is to be happy. At the end of the day, all the achievements and possessions mean nothing if they don\'t contribute to your genuine happiness.', author: 'Dalai Lama', category: 'LIFE' },
  { text: 'In three words I can sum up everything I\'ve learned about life: it goes on. No matter what happens — joy or sorrow, victory or defeat — life continues. And so must you.', author: 'Robert Frost', category: 'LIFE' },
  { text: 'Life is really simple, but we insist on making it complicated. We add layers of worry, ego, and attachment to what is fundamentally a beautiful, simple existence.', author: 'Confucius', category: 'LIFE' },
  { text: 'The biggest adventure you can take is to live the life of your dreams. Don\'t settle for a life of quiet desperation. Have the courage to pursue what truly sets your soul on fire.', author: 'Oprah Winfrey', category: 'LIFE' },
  { text: 'Life is either a daring adventure or nothing at all. Security is mostly a superstition. Avoiding danger is no safer in the long run than outright exposure.', author: 'Helen Keller', category: 'LIFE' },
  { text: 'Life is 10% what happens to us and 90% how we react to it. You cannot control the events of life, but you can always control your response to them.', author: 'Charles R. Swindoll', category: 'LIFE' },
  { text: 'The good life is one inspired by love and guided by knowledge. Balance your heart and mind, and you will find the path to a life well-lived.', author: 'Bertrand Russell', category: 'LIFE' },
  { text: 'Do not take life too seriously. You will never get out of it alive. Laugh at yourself, find joy in the absurd, and remember that nobody has it all figured out.', author: 'Elbert Hubbard', category: 'LIFE' },
  { text: 'You only live once, but if you do it right, once is enough. Don\'t wait for permission to live the life you want. This is your one shot — make it count.', author: 'Mae West', category: 'LIFE' },
  { text: 'Life is about making an impact, not making an income. The legacy you leave behind is measured not by what you accumulated, but by how many lives you touched.', author: 'Kevin Kruse', category: 'LIFE' },
  { text: 'Every moment is a fresh beginning. No matter what happened yesterday, today is a new day with new possibilities. You can start over anytime you choose.', author: 'T.S. Eliot', category: 'LIFE' },
  // ── FUNNY (12) ──
  { text: 'I am so clever that sometimes I don\'t understand a single word of what I am saying. Intelligence is a burden, and I carry it with great difficulty.', author: 'Oscar Wilde', category: 'FUNNY' },
  { text: 'People say nothing is impossible, but I do nothing every day. I am living proof that doing nothing is not only possible but can be perfected with practice.', author: 'A. A. Milne', category: 'FUNNY' },
  { text: 'I\'m not arguing, I\'m just passionately explaining why I\'m correct. There is a fine line between an argument and an educational lecture, and I walk it gracefully.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'If you think you are too small to make a difference, try sleeping with a mosquito. The smallest creatures can create the biggest annoyances, and so can you.', author: 'Dalai Lama', category: 'FUNNY' },
  { text: 'My fake plants died because I did not pretend to water them. Commitment issues extend even to my imaginary garden.', author: 'Mitch Hedberg', category: 'FUNNY' },
  { text: 'Behind every great man is a woman rolling her eyes. And behind every successful woman is herself, wondering why she puts up with all this nonsense.', author: 'Jim Carrey', category: 'FUNNY' },
  { text: 'The difference between stupidity and genius is that genius has its limits. Stupidity, on the other hand, is a renewable resource of infinite capacity.', author: 'Albert Einstein', category: 'FUNNY' },
  { text: 'I can resist everything except temptation. And snacks. And sleeping in. And buying things I don\'t need. Okay, maybe I can\'t resist much.', author: 'Oscar Wilde', category: 'FUNNY' },
  { text: 'Common sense is like deodorant. The people who need it most never use it. Walk through any public space and you will confirm this universal truth.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'Never put off till tomorrow what may be done the day after tomorrow just as well. Procrastination is an art form, and I consider myself a master.', author: 'Mark Twain', category: 'FUNNY' },
  { text: 'I always wanted to be somebody, but now I realize I should have been more specific. Being "somebody" is a very vague career goal.', author: 'Lily Tomlin', category: 'FUNNY' },
  { text: 'Age is an issue of mind over matter. If you don\'t mind, it doesn\'t matter. I plan to be immature for as long as humanly possible.', author: 'Mark Twain', category: 'FUNNY' },
  // ── LEADERSHIP (12) ──
  { text: 'A leader is one who knows the way, goes the way, and shows the way. Leadership is not about giving orders — it is about setting an example worth following.', author: 'John C. Maxwell', category: 'LEADERSHIP' },
  { text: 'Leadership is not about being in charge. It is about taking care of those in your charge. A true leader serves the people, not the other way around.', author: 'Simon Sinek', category: 'LEADERSHIP' },
  { text: 'The function of leadership is to produce more leaders, not more followers. The mark of a great leader is how many leaders they create, not how many followers they gather.', author: 'Ralph Nader', category: 'LEADERSHIP' },
  { text: 'Do not follow where the path may lead. Go instead where there is no path and leave a trail. True leaders are pioneers who create new possibilities.', author: 'Ralph Waldo Emerson', category: 'LEADERSHIP' },
  { text: 'Before you are a leader, success is all about growing yourself. When you become a leader, success is all about growing others.', author: 'Jack Welch', category: 'LEADERSHIP' },
  { text: 'If your actions inspire others to dream more, learn more, do more and become more, you are a leader. Leadership is measured by impact, not title.', author: 'John Quincy Adams', category: 'LEADERSHIP' },
  { text: 'A good leader takes a little more than his share of the blame and a little less than his share of the credit. Humility is the hallmark of true leadership.', author: 'Arnold H. Glasow', category: 'LEADERSHIP' },
  { text: 'Leadership and learning are indispensable to each other. The moment a leader stops learning, they stop leading effectively.', author: 'John F. Kennedy', category: 'LEADERSHIP' },
  { text: 'Leaders are made, they are not born. They are made by hard effort, which is the price all of us must pay to achieve any goal that is worthwhile.', author: 'Vince Lombardi', category: 'LEADERSHIP' },
  { text: 'Innovation distinguishes between a leader and a follower. Leaders embrace change; followers resist it.', author: 'Steve Jobs', category: 'LEADERSHIP' },
  { text: 'A true leader has the confidence to stand alone, the courage to make tough decisions, and the compassion to listen to the needs of others.', author: 'Douglas MacArthur', category: 'LEADERSHIP' },
  { text: 'The art of leadership is saying no, not yes. It is very easy to say yes. True leadership requires the wisdom to know when to say no.', author: 'Tony Blair', category: 'LEADERSHIP' },
  // ── EDUCATION (12) ──
  { text: 'Education is the most powerful weapon which you can use to change the world. No army can stop an idea whose time has come, and education plants those ideas.', author: 'Nelson Mandela', category: 'EDUCATION' },
  { text: 'The roots of education are bitter, but the fruit is sweet. The process of learning is often difficult and painful, but the rewards it brings are beyond measure.', author: 'Aristotle', category: 'EDUCATION' },
  { text: 'Education is not preparation for life; education is life itself. Learning doesn\'t stop when you leave school — it continues every single day you are alive.', author: 'John Dewey', category: 'EDUCATION' },
  { text: 'The beautiful thing about learning is that no one can take it away from you. Money can be stolen, possessions lost, but knowledge is yours forever.', author: 'B.B. King', category: 'EDUCATION' },
  { text: 'Live as if you were to die tomorrow. Learn as if you were to live forever. Every day is an opportunity to learn something new.', author: 'Mahatma Gandhi', category: 'EDUCATION' },
  { text: 'Intelligence plus character — that is the goal of true education. Education that builds only the mind without building the heart creates clever devils, not wise humans.', author: 'Martin Luther King Jr.', category: 'EDUCATION' },
  { text: 'The mind is not a vessel to be filled, but a fire to be kindled. True education ignites curiosity, it doesn\'t just dump information.', author: 'Plutarch', category: 'EDUCATION' },
  { text: 'Learning never exhausts the mind. The more you learn, the more you realize how much there is still to discover.', author: 'Leonardo da Vinci', category: 'EDUCATION' },
  { text: 'Education is what remains after one has forgotten what one has learned in school. The habits of thinking, questioning, and persevering are the real gifts of education.', author: 'Albert Einstein', category: 'EDUCATION' },
  { text: 'Tell me and I forget. Teach me and I remember. Involve me and I learn. True education is not passive — it is active, engaged, and experiential.', author: 'Benjamin Franklin', category: 'EDUCATION' },
  { text: 'The more that you read, the more things you will know. The more that you learn, the more places you\'ll go.', author: 'Dr. Seuss', category: 'EDUCATION' },
  { text: 'Education is the passport to the future, for tomorrow belongs to those who prepare for it today. Invest in your mind.', author: 'Malcolm X', category: 'EDUCATION' },
  // ── SPIRITUALITY (12) ──
  { text: 'The only journey is the one within. External achievements mean nothing if you have not explored the depths of your own soul.', author: 'Rainer Maria Rilke', category: 'SPIRITUALITY' },
  { text: 'Peace comes from within. Do not seek it without. No amount of external change can bring inner peace if your mind is at war with itself.', author: 'Buddha', category: 'SPIRITUALITY' },
  { text: 'You are not a drop in the ocean. You are the entire ocean in a drop. The entire universe exists within you, waiting to be discovered.', author: 'Rumi', category: 'SPIRITUALITY' },
  { text: 'The wound is the place where the Light enters you. Your deepest pain can become your greatest source of strength and wisdom.', author: 'Rumi', category: 'SPIRITUALITY' },
  { text: 'Be the change that you wish to see in the world. If you want peace, be peaceful. If you want kindness, be kind.', author: 'Mahatma Gandhi', category: 'SPIRITUALITY' },
  { text: 'The best way to find yourself is to lose yourself in the service of others. When you help others, you discover your true purpose.', author: 'Mahatma Gandhi', category: 'SPIRITUALITY' },
  { text: 'What we think, we become. Your thoughts shape your reality more than any external circumstance ever could.', author: 'Buddha', category: 'SPIRITUALITY' },
  { text: 'The soul always knows what to do to heal itself. The challenge is to silence the mind. Trust your inner wisdom.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'Your task is not to seek for love, but merely to seek and find all the barriers within yourself that you have built against it.', author: 'Rumi', category: 'SPIRITUALITY' },
  { text: 'Happiness is not something ready-made. It comes from your own actions. Peace is a practice, not a destination.', author: 'Dalai Lama', category: 'SPIRITUALITY' },
  { text: 'Yesterday I was clever, so I wanted to change the world. Today I am wise, so I am changing myself.', author: 'Rumi', category: 'SPIRITUALITY' },
  { text: 'The meaning of life is to find your gift. The purpose of life is to give it away. Your unique talents are not for you alone.', author: 'Pablo Picasso', category: 'SPIRITUALITY' },
  // ── NATURE (12) ──
  { text: 'Look deep into nature, and then you will understand everything better. The wisdom of the universe is written in the patterns of the natural world.', author: 'Albert Einstein', category: 'NATURE' },
  { text: 'In every walk with nature one receives far more than he seeks. The forest gives you exactly what you need, even if you didn\'t know you needed it.', author: 'John Muir', category: 'NATURE' },
  { text: 'Nature does not hurry, yet everything is accomplished. A river cuts through rock not because of its power, but because of its persistence.', author: 'Lao Tzu', category: 'NATURE' },
  { text: 'The earth has music for those who listen. The wind, the birds, the rustling leaves — there is a symphony playing all around you.', author: 'William Shakespeare', category: 'NATURE' },
  { text: 'Adopt the pace of nature: her secret is patience. Trees take decades to grow. Flowers bloom when they are ready. Trust the timing of your life.', author: 'Ralph Waldo Emerson', category: 'NATURE' },
  { text: 'Heaven is under our feet as well as over our heads. You don\'t need to look up to find paradise — it is right here, beneath the soil and stone.', author: 'Henry David Thoreau', category: 'NATURE' },
  { text: 'The clearest way into the Universe is through a forest wilderness. When you are lost among the trees, you find yourself.', author: 'John Muir', category: 'NATURE' },
  { text: 'Study nature, love nature, stay close to nature. It will never fail you. Nature is the most reliable teacher, healer, and friend you will ever have.', author: 'Frank Lloyd Wright', category: 'NATURE' },
  { text: 'Nature is not a place to visit. It is home. We are not separate from nature — we are a part of it.', author: 'Gary Snyder', category: 'NATURE' },
  { text: 'To sit in the shade on a fine day and look upon verdure is the most perfect refreshment. Simple pleasures are the sweetest.', author: 'Jane Austen', category: 'NATURE' },
  { text: 'If you truly love nature, you will find beauty everywhere. Even in the cracks of the sidewalk, life finds a way.', author: 'Vincent Van Gogh', category: 'NATURE' },
  { text: 'The mountains are calling and I must go. There is a wildness in the human spirit that only nature can satisfy.', author: 'John Muir', category: 'NATURE' },

  // ── NEW v1.1.0 QUOTES ──
  { text: 'Discipline is choosing what you want most over what you want now. Every small delayed gratification compounds into a future you will thank yourself for.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'Consistency beats intensity. Showing up average every day beats being extraordinary once a month.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'Your environment is either a fuel or a friction. Design your space, your circle, and your inputs like an athlete designs training.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'Ship imperfect work. Feedback from the real world is smarter than endless polishing in private.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'AI will not replace you. A person who uses AI well might. Learn the tools, keep the judgment.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'Write code for humans first, machines second. Clarity is a feature.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'Strong opinions, loosely held. Defend ideas with evidence, not ego — and change them when better data arrives.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'If a claim has no cost to be wrong, treat it lightly. Truth survives scrutiny; slogans fear it.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'प्रेम सिर्फ दिल की बात नहीं, रोज़ की छोटी-छोटी इज्ज़त है। जो रोज़ सम्मान देते हैं, वही रिश्ते लंबे चलते हैं।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'आज का छोटा सा सुधार, कल की बड़ी सफलता बन जाता है। रोज़ एक प्रतिशत बेहतर बनो।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'خاموشی بھی ایک جواب ہے۔ ہر بات کا جواب دینا ضروری نہیں۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'اپنی صبح کو اتنی طاقتور بناؤ کہ شام خود کامیاب ہو جائے۔', author: 'Sohel Khan', category: 'URDU' },
  { text: 'Love is a daily practice of kindness, not a single dramatic speech. The quiet consistent care is what lasts.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'Protect your peace the way you protect your passwords — carefully, and without apology.', author: 'Sohel Khan', category: 'WISDOM' },
  { text: 'A calm mind is a competitive advantage. Rest is not laziness; it is maintenance.', author: 'Sohel Khan', category: 'LIFE' },
  { text: 'I told my goals I was busy. They left. Now I keep better company.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'Leaders eat last, listen first, and credit the team publicly. Authority is a service, not a throne.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'Culture is what people do when nobody is watching. Set the standard, then live it.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'Education is not filling a bucket; it is lighting a fire that keeps seeking fuel.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'Read one page more than yesterday. Over a year you become a different person.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'Gratitude turns what you have into enough, and enough into a starting point for generosity.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'Stillness is not empty. In silence you finally hear what your life has been trying to say.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'Nature does not hurry, yet everything is accomplished. Align your pace with seasons, not only clocks.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'Walk outside without headphones once a week. Let the world remind you that you are part of something larger.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'Start before confidence arrives. Confidence is often the receipt, not the payment.', author: 'Sohel Khan', category: 'MOTIVATION' },
  { text: 'A focused hour can beat a distracted day. Protect your best attention like prime real estate.', author: 'Sohel Khan', category: 'SUCCESS' },
  { text: 'Good technology should make people feel more capable, not more confused.', author: 'Sohel Khan', category: 'TECH' },
  { text: 'Ask better questions before demanding faster answers. Direction matters more than speed.', author: 'Sohel Khan', category: 'CRITICAL_THINKING' },
  { text: 'Love grows where respect is repeated, especially on ordinary days.', author: 'Sohel Khan', category: 'LOVE' },
  { text: 'Wisdom is knowing which battles deserve your energy and which deserve your silence.', author: 'Sohel Khan', category: 'WISDOM' },
  { text: 'A simple life is not an empty life. It is a life with fewer things stealing your attention.', author: 'Sohel Khan', category: 'LIFE' },
  { text: 'My productivity plan was perfect until morning arrived with opinions.', author: 'Sohel Khan', category: 'FUNNY' },
  { text: 'The best leaders make responsibility feel shared and credit feel abundant.', author: 'Sohel Khan', category: 'LEADERSHIP' },
  { text: 'Learning becomes powerful when notes turn into practice and practice turns into character.', author: 'Sohel Khan', category: 'EDUCATION' },
  { text: 'Before changing the world, make your own heart a place where peace can live.', author: 'Sohel Khan', category: 'SPIRITUALITY' },
  { text: 'The sky changes color without asking permission. Let your growth be just as natural.', author: 'Sohel Khan', category: 'NATURE' },
  { text: 'Your mindset is the room where every decision is made. Keep it clean, honest, and ready for brave work.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'A strong mindset does not remove problems. It gives you a better posture while you solve them.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'Train your thoughts like you train your body. Repetition turns weak attention into steady strength.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'Do not let one bad hour rename your whole day. Reset quickly and keep moving with dignity.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'Growth begins when your excuses start sounding less convincing than your future.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'The mind becomes lighter when it stops arguing with reality and starts building from it.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'Confidence is useful, but commitment is stronger. Commitment keeps working even when confidence is quiet.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'Protect your attention. Whatever owns your focus slowly designs your life.', author: 'Sohel Khan', category: 'MINDSET' },
  { text: 'नया दिन नई सोच मांगता है। पुराने डर को साथ लेकर चलोगे तो नई मंजिल भी पुरानी लगेगी।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'दिल में भरोसा और हाथों में मेहनत हो तो रास्ता देर से सही, खुलता जरूर है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जिस काम से तुम्हारा भविष्य बेहतर होता है, उसके लिए आज थोड़ा असुविधा सहना भी समझदारी है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'लोगों की आवाज़ कम सुनो, अपने कर्म की आवाज़ ज्यादा मजबूत बनाओ।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'समय को पकड़ना मुश्किल है, लेकिन समय का सही उपयोग करना तुम्हारे हाथ में है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'जब मन हार मानने लगे, तब अपनी वजह याद करो। वजह मजबूत हो तो रास्ता फिर दिखने लगता है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'छोटे कदमों को कम मत समझो। हर लंबी यात्रा ऐसे ही चुपचाप आगे बढ़ती है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'अगर इरादा साफ है तो देर भी तैयारी बन जाती है। जल्दी से ज्यादा जरूरी स्थिरता है।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'अपने अंदर इतना उजाला रखो कि बुरे दिन भी तुम्हारा रास्ता पूरी तरह अंधेरा न कर सकें।', author: 'Sohel Khan', category: 'HINDI' },
  { text: 'हर रोज़ खुद को बेहतर बनाने वाला इंसान एक दिन अपनी ही पुरानी सीमा से आगे निकल जाता है।', author: 'Sohel Khan', category: 'HINDI' },
]

